INSERT INTO `sorts` VALUES (1,'Білий налив','сіро-зелені','середні суглинки і легкі чорноземи','Вегетаційний період: +18°C до +25°C. Мінімальна температура взимку: до -25°C (дерево витримує помірні морози). Критичні температури під час цвітіння: від 0°C до -2°C (морозостійкість квіток низька).','Садівництво','досить поширений сорт яблуні ранньолітнього дозрівання, виведений за допомогою народної селекції. Дерево має красиву пірамідальну (південний варіант) або округлу (північний варіант) крону, середні розміри і високу морозостійкість. Характеризується середньою стійкістю до парші листя й плодів. Молоді зразки починають плодоносити раніше, урожай дають щорічно, і він досить рясний. Перевагою сорту є раннє пишне цвітіння, бутони не бояться заморозків або холодної дощової погоди. Сорт середньостійкий до хвороб. Перші плоди дає на 4-5 рік. Плодоношення зосереджене на кільчатках. Плоди середні (100—130 г), достигають в кінці липня на початку серпня. Світло-жовтуватого кольору, кисло-солодкого смаку, з приємним ароматом, м\'якуш білий, ніжний, соковитий. Якщо перестигає, то стає борошнистим. Тривалість зберігання плодів — 2-3 тижні. Можна вживати одразу після збирання. Мають дуже тонку шкірку, без покривного забарвлення, плями від ударів і тиску стають одразу помітними. Тому транспортабельність досить низька.','https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Yellow_Transparent.jpg/1280px-Yellow_Transparent.jpg',1),(2,'Зарі','середнього розміру, темно-зелені, овальні, з легким блиском.','цей сорт добре росте на родючих суглинках, чорноземах, а також на легких супіщаних ґрунтах. Вимагає добре дренованих ґрунтів з помірною вологістю та слабокислою або нейтральною реакцією.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +34°C, але потребує регулярного поливу під час спеки для збереження якості плодів.','Садівництво','Дерево середньо- або сильноросле. Плоди великі, масою (200-250г.), кулясто-циліндричної форми. Шкірочка жовта, покрита штрихуватим, рожево-червоним рум\'янцем на всій поверхні плоду. М\'якоть жовта, щільна, хрустка, соковита, кисло-солодка з пряністю, відмінного смаку. Дозрівають плоди - 1-15 серпня. Зберігаються близько місяця, в холодильнику 1-2 місяці, в газовій камері до кінця зими. При зберіганні в звичайному підвалі спостерігається погіршення якостей плодів.Стійкість до грибкових хвороб висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/ieba7f54db0cf8a63/version/1676461201/image.jpg',1),(3,'Кармен де Сонен','середнього розміру, темно-зелені, овальні, з легким блиском.','цей сорт добре росте на родючих суглинках, чорноземах і піщаних ґрунтах, при умові хорошого дренажу. Підходить для слабокислих і нейтральних ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +25°C.\nМорозостійкість: витримує морози до -20°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак в умовах спеки потребує регулярного поливу для збереження здоров\'я дерева і якості плодів.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (120-150г.), мах - (200г.), приплюснуто-кулястої форми. Шкірочка жовто-зелена, покрита рожево-червоним рум\'янцем на всій поверхні плоду. М\'якоть біло-кремова, сколююча, соковита, ароматна, кисло-солодка, відмінного смаку.Дозрівають плоди - липень.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/ie5655ebd72a1f724/version/1676622506/image.jpg',1),(4,'Квінті','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт росте на родючих суглинках, чорноземах, а також на супіщаних та піщаних ґрунтах з хорошим дренажем. Підходить для слабокислих або нейтральних ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +32°C, однак в періоди високої температури необхідний регулярний полив для запобігання тепловому стресу.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (120-150г.), а при малому врожаї великі, порівняно одномірні, кулясті і подовжено-конічної форми. Шкірочка плоду гладка, ніжна, еластична, блискуча, іноді зі слабким восковим нальотом, має середню товщину і відрізняється значним ароматом. В знімальній зрілості основне забарвлення плоду зеленувато-жовте, а покривне - суцільне, але частіше має на більшій частині плоду темно-червоний або оранжево-червоний з малиновим відтінком рум\'янець. На слабо освітленній поверхні проглядаються переривчасті смуги на тлі слабкого мармурового рум\'янцю або основного забарвлення. Підшкірних точок багато, вони білі, іноді сірі, середньої величини, добре помітні. М\'якоть світло-кремова, середньої щільності, дрібнозерниста, соковита, кисло-солодка, приємного доброго смаку, із слабким ароматом. Кращі запилювачі: Віста Белла, Джуліред, Папіровка, Старк Ерліест. Знімальна й споживча стиглість у Степу настає в першій декаді липня, Лісостепу - у другій половині липня, на Поліссі - в третій декаді липня. Плоди дозрівають неодночасно, зберігаються 2-3 тижні. Сприйнятливість до парші середня, стійкість до борошнистої роси висока. Транспортабельність плодів середня. При транспортуванні на великі відстані товарність плодів значно знижується.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/ieea8b39621dcb4b0/version/1676623062/image.jpg',1),(5,'Колорит','середнього розміру, темно-зелені, овальні, з легким блиском.','цей сорт яблуні росте на родючих суглинках, чорноземах, а також на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для слабокислих і нейтральних ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +25°C.\nМорозостійкість: витримує морози до -23°C.\nМаксимальна плюсова температура: переносить температури до +35°C, однак за високих температур потребує регулярного поливу для запобігання перегріву та збереження якості плодів.','Садівництво','Дерево сильноросле. Плоди вище середнього розміру і великі, масою (150-210г.), кулясто-конічної форми, з гладкою поверхнею. Шкірочка середньої щільності, гладка, з восковим нальотом, суха, в період знімальної зрілості світло-жовта, пізніше яскраво-жовта, покрита темно-червоним розмитим рум\'янцем на більшій частині поверхні і невеликою кількістю дрібних малопомітних підшкірних цяток. М\'якоть біла, дрібнозерниста, ніжна, дуже соковита, ароматна, пряно-солодка, відмінного десертного смаку. Кращі запилювачі: Червоні вітрила, Мелба. У степовій частині Криму знімальна стиглість плодів настає в другій половині липня, споживча - з кінця липня до середини серпня. Вчасно зняті плоди можна зберігати 3 тижні. На дереві плоди тримаються добре, не обсипаються. Стійкість до парші середня, до борошнистої роси висока. Транспортабельність плодів хороша.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i10932726366e104b/version/1676735491/image.jpg',1),(6,'Леді Крим','середнього розміру, темно-зелені, овальні, з легким блиском.\n','сорт найкраще росте на родючих суглинках і чорноземах, але також може розвиватися на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для слабокислих і нейтральних ґрунтів з помірною вологістю. Ідеально підходить для степових зон.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +35°C, але в умовах спеки потребує регулярного поливу для запобігання перегріву та збереження здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру і великі, масою (160-190г.), округло-циліндричної форми. Шкірочка середньої товщини, гладенька, масляниста, блискуча, зі слабким восковим нальотом, жовта, покрита розмитим червоним рум\'янцем на більшій частині поверхні плоду. М\'якоть жовта, щільна, хрустка, соковита, ароматна, відмінного десертного смаку. Дозрівають плоди - серпень. Зберігаються протягом 3-5 тижнів.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i5d61fce20a4fa290/version/1676806972/image.jpg',1),(7,'Алка (синонім Валерія)','темно-зелені','родючі чорноземи або суглинкові ґрунти.','Оптимальна температура для росту: від +18°C до +24°C.\nМорозостійкість: витримує морози до -28°C.','Садівництво','Дерево середньоросле.Плоди середнього розміру і великі, масою (150-200г.), кулястої або кулясто-видовженої форми, не одномірні. Шкірочка гладенька, червона, вкрита густим, фіолетово-сизим, пруіновим нальотом, який легко зтирається. М\'якоть кремова (жовта), щільна, дрібнозерниста, соковита, солодка, з легкою кислинкою, гарного освіжаючого смаку.Дозрівають плоди - 20 серпня - 10 вересня.Стійкість до грибкових хвороб висока.Не уражується паршею і іншими грибковими хворобами. Чистий листовий апарат і плоди.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/ia3ddac33e73f3463/version/1675609508/image.jpg',1),(8,'Амбассі','темно-зелені, глянцеві.','добре дреновані родючі суглинки або чорноземи.','Оптимальна температура для росту: від +18°C до +25°C. Морозостійкість: витримує морози до -30°C. Сухостійкість: витримує жару до +35°C.','Садівництво','Дерево в молодому віці сильноросле, після вступу в пору плодоношення стає середньорослим. Плоди середнього розміру і великі, масою (145-180г.), овально-циліндричної форми, трохи видовжені. Шкірочка жовта, вкрита інтенсивно червонувато-помаранчевим смугастим рум\'янцем на 50-70% поверхні плоду. М\'якоть жовтувата, щільна, хрустка, соковита, ароматна, дуже солодка. Найкращі запилювачі: Айдаред, Найдаред, Пауларед, Алкмене, Гала, Голден Делішес, Делікатес, Джеймс Грів, Лігол, Ельстар, Фієста, Санрайз, Чемпіон, Ерлі Женева, Діскавері. Є відмінним запилювачем для інших сортів яблук. Знімальна зрілість плодів - 25 серпня - 10 вересня.Не вимогливий до умов вирощування. Стійкість до грибкових хвороб середня. Сорт слабо стійкий до парші та борошнистої роси, уражується бактеріальним опіком. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/ibd89637f62bf4fea/version/1675614764/image.jpg',1),(9,'Мантет','великі, світло-зелені, овальні, з гладкою поверхнею.','орт добре росте на родючих суглинках, чорноземах, піщаних ґрунтах (за умови внесення органіки), а також на слабокислих або нейтральних ґрунтах із гарним дренажем.','Оптимальна температура: від +18°C до +25°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить до +35°C за умови достатнього поливу.','Садівництво','Дерево середньоросле.Плоди середніх розмірів, масою (110-140г.), широко-округло-конічної форми, у верхній частині трохи ребристі, середньої одномірності. Шкірочка тонка, ніжна, гладка, жовто-зелена, з рожево-червоним смугасто-розмитим рум\'янцем на більшій частині поверхні плоду, дрібними сіруватими підшкірними крапками і легким сизим нальотом. М\'якоть біла, з рожевими прожилками, соковита, ніжна, середньої щільності, ароматна, солодка зі слабким кислуватим присмаком, десертного смаку.Кращі запилювачі: Віста Белла, Джуліред, Мелба, Папіровка.Знімальна й споживча стиглість у Степу України настає - 10-20 липня, в Лісостепу - 20-30 липня, на Поліссі - 1-10 серпня. Дозрівання плодів неодночасне, розтягнуте - з середини липня до 15-20 серпня. Збирають плоди в 2-3 прийоми. Плоди швидко перестигають. Зберігаються в звичайних умовах - 10-15 днів.Стійкість до борошнистої роси висока, до парші - середня. У вологі роки плоди і листя уражаються паршею. Транспортабельність плодів середня.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i91b2b2485343dcfe/version/1676967626/image.jpg',1),(10,'Аполон','темно-зелені, овальні, з легким блиском.','дерево добре росте на родючих суглинках, чорноземах, слабокислих або нейтральних ґрунтах. Також може адаптуватися до піщаних ґрунтів за умови регулярного поливу та внесення органіки.','Оптимальна температура: від +18°C до +25°C.\nМорозостійкість: витримує морози до -24°C.\nМаксимальна плюсова температура: переносить до +34°C за умови достатньої вологості ґрунту.','Садівництво','Дерево середньоросле.Плоди великі, масою (180-200г.), кулясто-конічної форми. Шкірочка блискуча, жовта, вкрита темнувато-червоним плямистим рум\'янцем на більшій частині поверхні плоду. М\'якоть кремова, середньої щільності, хрустка, солодка з невеликою кислинкою, ароматна, десертного відмінного смаку. Дозрівають плоди - 25-30 липня.Стійкість до грибкових хвороб висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=280x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/ifd2805eb001b5861/version/1675628623/image.jpg',1);
INSERT INTO `sorts` VALUES (11,'Аромат де Варе','темно-зелені, великі, з гладкою поверхнею.','підходить для вирощування на родючих суглинках, чорноземах, а також на слабокислих піщаних або глинистих ґрунтах із гарним дренажем. Найкраще розвивається на добре зволожених і поживних землях.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -26°C.\nМаксимальна плюсова температура: переносить до +32°C за умови регулярного поливу.','Садівництво','Дерево слабо- або середньоросле. Плоди середнього розміру, масою (130-170г.), кулястої або кулясто-плескатої форми, з незначною ребристістю. Шкірочка тоненька, жовтувато-зелена, вкрита яскравим рожево-червоним, смугастим рум\'янцем на більшій частині поверхні плоду. М\'якоть кремова, щільна, хрустка, ніжна, соковита, ароматна, солодка, відмінного смаку.Найкращі запилювачі: Квінті, Ерлі Мак, Айдаред.Знімальна зрілість плодів настає - 20-30 червня і закінчується на початку серпня (дозрівання плодів дуже розтягнуте) - в середньому 20-30 липня. Стійкість до грибкових хвороб висока. Паршею не уражується.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i66bb85b37925079c/version/1675628682/image.jpg',1),(12,'Астраханське біле','зелені, овальні, з легким блиском.','підходить для родючих суглинків, чорноземів, а також для легких піщаних ґрунтів, добре дренованих і з помірною вологістю.','Оптимальна температура: від +18°C до +25°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить до +35°C за умови достатнього поливу.','Садівництво','Дерево сильноросле. Плоди меньше середнього розміру і середні, масою (80-130г.), плоско-кулястої або кулясто-конічної форми, на верхівці з невеликою ребристістю, асиметричні, не одномірні. Шкірочка тоненька, тендітна, слабо ароматна, дуже ніжна, гладенька, слабо блискуча, на дотик суха, в період споживчої зрілості - матово-жовта, з легким рожево-червоним смугасто розмитим рум\'янцем на сонячній стороні, іноді з легким сизуватим нальотом. Підшкірні крапки численні, добре помітні на зеленому або рожевому тлі. М\'якоть біла, ніжна, дрібнозерниста, соковита, доброго, кисло-солодкого смаку, але швидко стає борошнистою, особливо при запізнілому знятті плодів з дерева. Найкращі запилювачі: Апорт, Боровинка, Пепин литовський, Королівське солодке, Антонівка звичайна, Яндиковське.Знімальна зрілість плодів настає в другій половині липня і часто триває до середини серпня. Яблука знімають в кілька прийомів (неодночасне дозрівання), за 5-7 днів до настання споживчої зрілості. Спостерігається схильність до здріблення і розтріскування плодів. Транспортабельність плодів низька.Стійкість до парші, борошнистої роси і плодової гнилі, а також до пошкоджень плодожеркою і яблуневим пильщиком - середня.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i3eb90e81477ca5ad/version/1675678298/image.jpg',1),(13,'Боровинка','темно-зелені, середнього розміру, овальні, з легкою загостреністю.','підходить для родючих суглинків, чорноземів, а також для піщаних і супіщаних ґрунтів, добре дренованих і з помірною вологістю. Може рости на слабокислих або нейтральних ґрунтах.','Оптимальна температура для росту: від +18°C до +22°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: сорт може переносити температури до +30°C, але при тривалих спекотних умовах потребує регулярного поливу для запобігання тепловому стресу та збереження високої якості плодів.','Садівництво','Дерево середньоросле. Плоди середнього та вище середнього розміру, масою (130-160г.), плоско-округлої правильної форми, без помітних ребер, майже точені, з гладкою поверхнею, симетричні. Шкірочка світло-зелена або жовта, з рожевим відтінком, покрита крапчато-смугастим рум\'янцем по рожевому фону або більшій частині плоду. На шкірці помітні численні, світлі, підшкірні точки. Восковий наліт слабкий, шкірка гладка, суха. М\'якоть кремова, соковита, трохи грубувата, кисло-солодкого смаку (з помітним переважанням кислоти). Дозрівають плоди - 15-30 серпня. Висять на дереві 2-3 тижні. Сорт невибагливий і порівняно стійкий до грибкових хвороб. Транспортабельність плодів хороша.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/id09dd023600accbc/version/1675776316/image.jpg',1),(14,'Вільямс Прайд (Williams Pride)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.\n','добре росте на родючих суглинках, чорноземах, а також на слабокислих або нейтральних ґрунтах з хорошим дренажем. Може адаптуватися до піщаних ґрунтів за умови регулярного поливу.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +35°C, але для збереження високої якості плодів необхідний достатній рівень вологості ґрунту в спекотні періоди.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (120-160г.), кулясто-конічної форми, деякі асиметричні, середньої одномірності.Шкірочка тоненька, щільна, еластична, гладенька, слабо ребриста у верхній половині, жовтувато-біла з розмитим, рожево-темно-червоним покривним забарвленням на більшій частині поверхні плоду, з сильним восковим нальотом, середньою кількістю дрібних, рожевих, добре помітних підшкірних крапок. М\'якоть жовтувато-кремова, з рожевими прожилками, середньозерниста, щільна, хрустка, соковита, терпко-кисло-солодка. Найкращі запилювачі: Катя, Папіровка, Джулія, Мелба. Знімальна зрілість плодів в Поліссі та Лісостепу настає в кінці липня - першій декаді серпня. Дозрівають плоди на дереві не одночасно. Збирають плоди в 2-3 прийоми. Зберігаються плоди близько 1,5 місяця. Імунний до парші, стійкість до борошнистої роси - висока, сильно сприйнятливий до європейського раку, середньо уражається плодовою гниллю. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/ie67b08803ce1b4df/version/1675859844/image.jpg',1),(15,'Віста Белла (Vista Bella)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на піщаних та супіщаних ґрунтах, за умови гарного дренажу та достатнього зволоження. Підходить для слабокислих або нейтральних ґрунтів.сорт добре росте на родючих суглинках, чорноземах, а також на піщаних та супіщаних ґрунтах, за умови гарного дренажу та достатнього зволоження. Підходить для слабокислих або нейтральних ґрунтів.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +35°C, але в умовах високої спеки необхідний регулярний полив, щоб запобігти тепловому стресу.','Садівництво','Дерево сильноросле. Плоди середньої величини, масою (140-150г.), сплющено-кулястої форми, одномірні. Шкірочка середньої товщини, щільна, еластична, гладка, суха, світло-зелена, з привабливим темно-червоним, розмитим, покривним рум\'янцем по всій поверхні плоду, численними, великими, середньої величини, світлими, підшкірними крапками і слабким восковим нальотом. М\'якуш світло-кремовий, ніжний, соковитий, відмінного, гармонійного, кислувато-солодкого смаку. Найкращі запилювачі: Квінті, Мантет, Мелба, Папіровка, Ямба, Джеймс Грів, Ерлі Женева. Знімальна зрілість плодів в умовах Полісся і Лісостепу настає в другій-третій декаді липня, раніше Білого наливу (на 5-7 днів). Дозрівають плоди нерівномірно. У холодильнику плоди зберігаються до 1 місяця. Стійкість до парші та європейського раку - низька, до борошнистої роси - середня. Висока сприйнятливість до збудників основних грибних хвороб. Шкідники: тля, червоний павутинний кліщ, плодожерка. Транспортабельність плодів середня.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i9e29fd5479a786f1/version/1675860455/image.jpg',1),(16,'Делела (Delela)','середнього розміру, темно-зелені, овальні, з помірним блиском.','сорт адаптований до різних типів ґрунтів, таких як родючі суглинки, чорноземи, а також легкі піщані та супіщані ґрунти, за умови доброго дренажу. Придатні ґрунти мають бути помірно вологими і слабокислими або нейтральними.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +32°C, але за високих температур необхідний регулярний полив.','Садівництво','Дерево середньоросле. Плоди великі, масою (150-200г.), кулясто-циліндричної форми. Шкірочка тоненька, гладенька, жовтувато-зелена, вкрита штрихуватим або розмитим червоно-оранжевим рум\'янцем на більшій частині поверхні плоду. М\'якоть кремова, щільна, сколююча, хрустка, соковита, аромат сильний, кисло-солодка, відмінного смаку. Найкращі запилювачі: Ельстар, Гала, Айдаред, Джеймс Грів, Лобо, Санрайс. Дозрівають плоди - 20 серпня. Зберігаються в холодильнику - 2-3 місяці. Стійкість до парші та борошнистої роси середня, до хвороб кори і деревини  слабка.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i6b711e04cf0cfb19/version/1676195806/image.jpg',1),(17,'Діскавері (Discovery)','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на легких піщаних і супіщаних ґрунтах. Вимагає добре дренованих і зволожених ґрунтів з нейтральною або слабокислою реакцією.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, але за умов високої спеки необхідний регулярний полив для підтримки здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (120-150г.), правильної, плоско-кулястої форми. Шкірочка жовтувато-зелена, з сонячної сторони плоду майже вся поверхня покрита яскравим темно-червоним  рум\'янцем. М\'якоть кремова, шільна, хрустка, середньої соковитості, з невеликим ароматом, кисло-солодка, відчувається слабко виражений присмак полуниці. Цікавою особливістю даного сорту є те, що колір шкірочки може злегка \"кровоточити\" в м\'якоть. Цвіте в ранні терміни, сорт трохи чутливий до заморозків. Хороший запилювач для багатьох сортів різного терміну дозрівання. Дозрівають плоди - 10 серпня. Зберігаються плоди 1-2 тижні в холодильнику. Десертний столовий сорт. Плоди не призначені для тривалого зберігання, споживаються протягом тижня після зняття з дерева. Мало сприйнятливий до парші.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/ifb290421fefe9f15/version/1676194935/image.jpg',1),(18,'Джорж Кав  (George Cave)','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт адаптований до різних ґрунтів, включаючи родючі суглинки, чорноземи, а також піщані ґрунти за умови належного дренажу. Підходить для слабокислих і нейтральних ґрунтів.','Оптимальна температура: від +18°C до +25°C.\nМорозостійкість: витримує морози до -28°C.\nМаксимальна плюсова температура: переносить температури до +35°C, але за високих температур потребує регулярного поливу для запобігання тепловому стресу.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (110-140г.), зрізано-кулясто-конічної форми, одномірні. Шкірочка середньої товщини, щільна, еластична, слабо блискуча, суха, світло-жовта, покрита яскраво-червоним смугасто-плямистим рум\'янцем на більшій частині поверхні плоду і слабким восковим нальотом. М\'якоть світло-жовта (кремова), дрібнозерниста, щільна, соковита, ароматна, кисло-солодка, відмінного смаку. Найкращі запилювачі: Папіровка, Мелба, Квінті, Джерсімак. Знімальна й споживча стиглість плодів - 20 липня - 10 серпня. Дозрівають неодночасно, збір плодів у 2-3 прийоми. При перезріванні обсипаються, але не втрачають своїх смакових якостей. У холодильнику плоди можуть зберігатися - 1-1,5 місяці. Стійкість проти парші та борошнистої роси висока, плодової гнилі - вище середньої. Вимогливий до умов вирощування. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i4de5d4dd44cd6e18/version/1676282475/image.jpg',1),(19,'Джулі Ред (July Rеd)','середнього розміру, темно-зелені, овальні, з гладкою поверхнею.','сорт добре росте на родючих суглинках, чорноземах, а також на легких піщаних ґрунтах, з хорошим дренажем. Ґрунти повинні бути помірно вологими, слабокислими або нейтральними.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +32°C, але потребує регулярного поливу під час спеки для запобігання перегріву.','Садівництво','Дерево сильноросле. Плоди середнього та вище середнього розміру, масою (130-160г.), кулясто-конічної форми, іноді асиметричні. Шкірочка тонка, щільна, еластична, гладка, злегка масляниста, світло-жовта, покрита рожево-червоним смугасто-розмитим рум\'янцем майже по всій поверхні плоду, з дрібними жовтуватими підшкірними цятками. М\'якоть рожево-біла, середньої щільності, ніжна, соковита, кисло-солодка, гарного  смаку. Найкращі запилювачі: Віста Белла, Джерсімак, Мантет, Папіровка, Дельбард Жубіле, Елізе, Голден Делішес, Джонаголд, Санрайз. Сорт схильний до перевантаження врожаєм, що призводить до періодичності плодоношення. Необхідно проводити обрізку для нормування врожаю. Знімальна й споживча стиглість - 20 липня - 10 серпня. Плоди дозрівають одночасно. Зберігаються плоди протягом 1 місяця. У холодильнику зберігаються до 2-х місяців. Залишені на дереві плоди швидко перестигають і обсипаються. Потребують своєчасного збору. Сприйнятливість до парші середня, до борошнистої роси - нижча за середню, до грибкових хвороб кори і деревини - слабка. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i1397ac3a84eba139/version/1676282154/image.jpg',1),(20,'Донешта','великі, темно-зелені, овальні, з гладкою поверхнею.','цей сорт добре росте на родючих суглинках, чорноземах, а також на легких супіщаних ґрунтах. Вимагає добре дренованих ґрунтів, з помірною вологістю і нейтральною або слабокислою реакцією.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -28°C.\nМаксимальна плюсова температура: переносить температури до +33°C, однак за високих температур потребує регулярного поливу для запобігання тепловому стресу.','Садівництво','Дерево сильноросле. Плоди середнього та вище середнього розміру, масою (140-190г.), сплющено-кулясті з п\'ятьма згладженими часто асиметричними ребрами. Шкірочка середньої товщини, гладенька, блискуча, білувато-жовта, з дрібними зеленими підшкірними цятками, зосередженими на верхівці плоду. М\'якоть жовтувато-кремова, середньої щільності, соковита, кисло-солодка, приємного смаку. Кращі запилювачі: Папіровка, Антонівка звичайна, Пепінка золотиста, Боровинка. Знімальна й споживча стиглість - 15 серпня. Дозрівання не одночасне. Збір плодів в 2 прийоми. Зберігаються в звичайному сховищі - 1 місяць, в холодильнику - близько 2-х місяців. Спостерігається сувора періодичність плодоношення. При перезріванні плоди обсипаються і гниють, м\'якоть стає пухкої, втрачає соковитість.Стійкість до парші та борошнистої роси вище середньої, до плодової гнилі - середня. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i555ee5710df3adc1/version/1676281484/image.jpg',1),(21,'Амулет','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для слабокислих і нейтральних ґрунтів з помірною вологістю. Потребує регулярного поливу в умовах спеки.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -36°C.\nМаксимальна плюсова температура: переносить температури до +32°C, однак в умовах спеки потребує регулярного поливу для запобігання перегріву та збереження здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди вище середнього розміру і великі, масою (160-200г.), кулясто-конічної форми зі слабкою ребристістю на верхівці, одномірні. Шкірочка середньої товщини, блискуча, еластична, без слідів оржавленості, зеленувато-жовта, вкрита інтенсивним темнувато-червоним розмитим рум\'янцем майже по всій поверхні плоду. М\'якоть кремова, середньої щільності, дрібнозерниста, ламка, соковита, ароматна, кисло-солодка, доброго смаку. Найкращі запилювачі: Вітос, Пріам, Флоріна, Фрідом, Чемпіон, Глостер, Імрус. Знімальна зрілість плодів - 15 вересня. Період споживання плодів - з жовтня по грудень. Після дозрівання плодів спостерігається їх повне осипання. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/id52ac48c33574731/version/1675612944/image.jpg',2),(22,'Вітос','середнього розміру, темно-зелені, овальні, з помірним блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для слабокислих і нейтральних ґрунтів з помірною вологістю. Потребує регулярного поливу в умовах спеки.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +32°C, однак в умовах спеки потребує регулярного поливу для запобігання перегріву та збереження здоров\'я дерева.','Садівництво','Дерево сильноросле. Плоди вище середніх розмірів і великі, масою (180-225г.), одномірні, сплющено-кулястої форми. Шкірочка тонка, середньої щільності, блискуча, гладка, помірно масляниста, жовто-зелена, з тьмяно-червоним смугасто-розмитим рум\'янцем, який найчастіше покриває 1/3-1/2 поверхні плоду, середньою кількістю дрібних, світлих, підшкірних точок і легким сизим нальотом. М\'якоть кремово-біла, дрібнозерниста, дуже ніжна, соковита, запашна, гармонійного кисло-солодкого смаку. Найкращі запилювачі: Амулет, Скіфське золото, Джеймс Грів, Катя, Лобо, Делічія. Знімальна зрілість плодів настає в середині вересня. Зволікання із збиранням врожаю призводить до осипання і поганій лежкості плодів. Імунний проти п\'яти рас парші (донор гена Vf), стійкість до борошнистої роси - середня, проти європейського раку - висока.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i9edff31638f90b8b/version/1675862517/image.jpg',2),(23,'Гала Шніга (Gala Szniga)','середнього розміру, темно-зелені, овальні, з легким блиском.','орт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для слабокислих і нейтральних ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +25°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +35°C, однак в умовах спеки потребує регулярного поливу для запобігання перегріву та підтримання здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру та великі, масою (130-150г.), кулясто-конічної форми, верхівка зі слабкою ребристістю, одномірні. Шкірочка тоненька, щільна, блискуча, суха на дотик, основне забарвлення - жовте, покривне - яскраво-червоний рум\'янець на більшій частині поверхні плоду, з розмитими темно-червоними, слабко вираженими смугами та штрихами і світлими підшкірними крапками. Рум\'янець світліший, ніж у сорту Гала Галаксі. Забарвлюються плоди досить рано. М\'якоть кремова, щільна, хрустка, дуже соковита, солодка з легкою кислинкою, доброго смаку. Найкращі запилювачі: Бребурн, Дельблаш (Тентейшн), Гренні Смітт, Пінова, Ельстар, Фуджі, Айдаред, Голден Делішес, Ред Делішес, Рубенс, Рубінетте, Еверест. Дозрівають плоди - 1-15 вересня. Стійкість до грибкових хвороб середня (чутливість до парші висока, до борошнистої роси середня). Сприятливий до хвороб кори і деревини. Транспортабельність плодів середня.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i765a43536a677d2d/version/1675941142/image.jpg',2),(24,'Гала Галаксі (Gala Galaxy)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах і супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +32°C, однак в умовах високих температур потребує регулярного поливу для запобігання перегріву та підтримки здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди великі, масою (160-240г.), округло-конусоподібної форми, одномірні, за формою нагадують яблука сорту Гала Маст. Шкірочка блискуча, темно-червона з штрихами і світлими підшкірними крапками. Забарвлення плодів з\'являється в кінці серпня. М\'якоть жовто-кремова, щільна, дрібнозерниста, хрустка, соковита, ароматна, солодка з легкою кислинкою, відмінного смаку. Кращі запилювачі: Діскавері, Ельстар, Глостер, Голден Делішес, Айдаред, Чемпіон, Пауларед, Мелроуз, Ред Делішес, Фуджі. Дозрівають плоди - 10-20 вересня. На дереві швидко перестигають, при запізнілому зборі розтріскуються. Потребує сорт своєчасного збору плодів. Плоди не обсипаються, міцно висять на дереві. Стійкість до парші та бактеріального опіку - середня, до борошнистої роси - слабка. При зберіганні плоди можуть урожуватися сірою гниллю.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/if0c6e0166b8c2da3/version/1675941284/image.jpg',2),(25,'Гала Наталі (Gala Natali)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для слабокислих і нейтральних ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак в умовах спеки потребує регулярного поливу для запобігання перегріву та збереження здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (150-170г.), кулясто-конусної форми. Шкірочка гладенька, жовтувато-зелена, вкрита червоним смугастим рум\'янцем на 70-80% поверхні плоду. М\'якоть жовта, щільна, ароматна, солодка, відмінного десертного смаку. Найкращі запилювачі: Еліза, Лігол, Глостер, Бребурн, Ельстар, Фієста, Фуджі, Голден Делішес, Джестер, Мелроуз, Ред Делішес, Еверест, Професор Шпрінгер, Мутсу, Рубінстар. Дозрівають плоди - вересень, дозрівання: на 7-10 днів пізніше, ніж сорт Гала Маст. Зберігаються в холодильнику до березня. Стійкість до парші середня, борошнистої роси нижча за середню, хвороби кори і деревини слабка, бактеріального опіку слабка. ','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/id632aac51fef2256/version/1675941399/image.jpg',2),(26,'Грінс Лівз (Greensleeves)','великі, темно-зелені, з матовим блиском, овальної форми.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і легких піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів. Потребує помірної вологості ґрунту.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак за умов високих температур потребує регулярного поливу для запобігання перегріву дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (130-150г.), одномірні, кулясті або кулясто-конічної форми. Шкірочка середньої товщини, злегка шорстка, суха на дотик, іноді з сітчастою сірувато-бурою оржавленністю (у вигляді сітки), зеленувато-жовта, іноді з легким рум\'янцем на сонячній стороні плоду. М\'якоть жовто-кремова, щільна, хрустка, дрібнозерниста, дуже соковита, ароматна, насиченого гармонійного, кисло-солодкого смаку. Найкращі запилювачі: Амулет, Імрус, Делічія, Чемпіон, Прима, Пріам, Ліберті. Знімальна й споживча стиглість плодів наступають одночасно - в середині вересня. У холодильнику плоди можуть зберігатися - 2-2,5 місяця, в підвалі - 1 місяць. Має імунітет до 5-ти рас парші, високостійкий до борошнистої роси та бурої плямистості листя. Транспортабельність плодів середня.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i4412664b496f280c/version/1676115436/image.jpg',2),(27,'Грів Руж','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт найкраще росте на родючих суглинках і чорноземах, але також може рости на супіщаних ґрунтах з хорошим дренажем. Підходить для слабокислих і нейтральних ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -20°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак при високих температурах потребує регулярного поливу для підтримання здоров\'я дерева та врожайності.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (110-150г.), вирівняні, округлі, слабо- і середньо сплощені, слабо ребристі, злегка округло-конічні. Шкірочка світло-зелена - під час знімальної зрілості, жовта при повному дозріванні, покривне забарвлення у вигляді мармурового, скрапленого помаранчево-червоного рум\'янцю іноді з малиновими штрихами майже на всій поверхні плоду. М\'якоть біла, з блідо-жовтим відтінком, щільна, соковита, кисло-солодкого смаку з сильним ароматом. У лежці стає більш солодкою, приємною, ніжною, соковитою. Стійкість до грибкових хвороб середня. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i422b644e1d07bf6d/version/1676028070/image.jpg',2),(28,'Джеймс Грів Спур','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для слабокислих і нейтральних ґрунтів з помірною вологістю.\n','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -20°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак в умовах високих температур потребує регулярного поливу для підтримання здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди великі, масою (150-180г.), кулясто-конічної форми, трохи приплюснуті, злегка ребристі. Шкірочка середньої товщини, щільна, блискуча, зеленувато-жовта, покрита помаранчевими смугами і червоним розмитим рум\'янцем на сонячній стороні плоду. М\'якоть кремова, середньої щільності, дрібнозерниста, дуже соковита, приємного солодко-винного смаку. Знімальна зрілість плодів - кінець серпня - початок вересня. Дозрівають плоди на тиждень пізніше сорту Слава переможцям. У холодильнику зберігаються до січня. Період споживання - вересень-жовтень. Стійкість до борошнистої роси і парші середня.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/iae19d5c47800c7df/version/1676384934/image.jpg',2),(29,'Джестер','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.\n','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, але потребує регулярного поливу в умовах спеки для запобігання перегріву і збереження здоров\'я дерева.','Садівництво','Дерево слаборосле. Плоди вище середнього розміру, масою (150-180г.), кулясто-конічної форми, одномірні. Шкірочка гладенька, без оржавленості, зеленувато-жовта, покрита штриховато-розмитим червоним рум\'янцем на більшій частині поверхні плоду. М\'якоть кремово-біла, соковита, ароматна, кисло-солодка, відмінного смаку. Дозрівають плоди з другої декади вересня. При дозріванні не обсипаються. У холодильнику зберігаються до 4-х місяців. Стійкість до грибкових хвороб висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i80774c12acdb9302/version/1676196924/image.jpg',2),(30,'Джоніка (Jonica)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і легких піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.\n','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +35°C, однак в умовах високих температур потребує регулярного поливу для запобігання перегріву і підтримання здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди вище середнього розміру, масою (170-200г.), кулясто-ширококонічної форми, більш витягнуті, ніж яблука сорту Джонаголд, злегка ребристі або без ребер. Шкірочка середньої щільності і товщини, гладенька, блискуча, жирна на дотик, при знімальній зрілості - зеленувато-жовта, пізніше жовта, з зеленуватим відтінком і яскраво-червоним розмитим рум\'янцем майже по всій поверхні плоду і з досить рідкими, середніх розмірів і дрібними, світло-жовтими, добре помітними підшкірними цятками. М\'якоть жовта, іноді з зеленими прожилками, середньої щільності, дрібнозерниста, дуже соковита, гармонійного, кисло-солодкого смаку, з сильним ароматом. Десертний сорт. Знімна стиглість настає наприкінці вересня, споживча — у січні. Зберігаються плоди в холодильнику до квітня. Стійкість до парші та борошнистої роси висока. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i06c0ec9e3e50875b/version/1676285185/image.jpg',2);
INSERT INTO `sorts` VALUES (31,'Делікатес (Delikates)','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак в умовах спеки потребує регулярного поливу для збереження здоров\'я дерева і гарного врожаю.','Садівництво','Дерево слабо- або середньоросле. Плоди вище середнього розміру, масою (140-180г.), кулясто-конічної (овальної) форми, трохи приплюснуті, одномірні. Шкірочка світло-жовта, покрита яскраво-червоним смугасто-розмитим рум\'янцем на 70-80% поверхні плоду. М\'якоть біла з зеленими прожилками, дрібнозерниста, щільна, дуже ніжна, соковита, ароматна, кисло-солодка, відмінного смаку. Десертний сорт. Найкращі запилювачі: Амбассі, Ельстар, Ідаред, Джонамак, Лігол, Найдаред, Спартан, Джеймс Грів, Мекинтош, Слава Переможцям, Целеста, Теремок, Чемпіон, Голден Делішес. Дозрівають плоди - 10-15 вересня. Дозрівання розтягнуте до кінця вересня. Зберігаються в холодильнику - 2-3 місяці. При дозріванні осипаються.При стандартних хімічних обробках стійкість до грибкових хвороб висока. Без обробок стійкість до парші - середня, борошнистої роси - висока, до європейського раку і бактеріального опіку - середня. Сильно уражується плодожеркою. Транспортабельність плодів середня.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/iaa5f136804d06665/version/1676385407/image.jpg',2),(32,'Делічія (Delicia)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -20°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак за умов високих температур потребує регулярного поливу для підтримки здоров\'я дерева та врожайності.','Садівництво','Дерево слабо- або середньоросле. Плоди середнього розміру і великі, масою (150-190г.), плоско-кулясто-конічної форми, деякі асиметричні, середньої одномірності. Шкірочка тонка, середньої щільності, суха, гладка із середнім блиском, зеленувато-жовта, покрита інтенсивним темно-червоним розмито-смугастим рум\'янцем на більшій частині поверхні плоду, з невеликою кількістю дрібних слабо помітних підшкірних цяток і середнім сизим нальотом. М\'якоть біла, іноді рожево-біла, дрібнозерниста, середньої щільності, соковита, ароматна, кисло-солодка, відмінного смаку. Кращі запилювачі: Антонівка звичайна, Джеймс Грів, Слава переможцям, Жовтневе Дуки. Знімальна й споживча стиглість настає - 1-10 вересня. У холодильнику плоди зберігаються - 2,5-3 місяці. При зберіганні можливо спухання плодів. Стійкість до парші, борошнистої роси та бурої плямистості висока, плодової гнилі середня. Транспортабельність і товарність плодів високі.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i4b6f26bfc3d25e55/version/1676192587/image.jpg',2),(33,'Жовтневе Дукі','великі, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: зимостійкість середня, сорт недостатньо зимостійкий для регіонів Лісостепу та Полісся України. Вимагає захисту від морозів в умовах суворих зим.\nМаксимальна плюсова температура: переносить температури до +32°C, однак за умов високих температур потребує регулярного поливу для підтримання здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середніх розмірів, масою (110-145г.), середньої одномірності, сплющено-округлої форми.  Шкірочка тонка, гладка, блискуча, масляниста, яскраво-жовта з буро-червоним розмитим рум\'янцем і зеленувато-бурими підшкірними крапками. М\'якоть кремово-жовта, дрібнозерниста, щільна, дуже соковита, ламка, ароматна, відмінного, кисло-солодкого смаку. Найкращі запилювачі: Антонівка звичайна, Алкмене, Слава переможцям, Джеймс Грів Спур. Знімальна й споживча стиглість настає в кінці серпня - напочатку вересня. При запізненні із збиранням врожаю спостерігається сильне обпадання плодів, швидке перезрівання, спухання, водянисте розкладання м\'якоті, плоди втрачають смакові якості. У звичайному сховищі зберігаються - 2-3 тижні, в холодильнику - 1-1,5 місяці. Стійкість до парші - вище середньої, проти борошнистої роси - невисока. Потребує інтенсивного захисту від борошнистої роси і нормування квіток і зав\'язі. Транспортабельність плодів середня.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/if61db53e2555192a/version/1676460877/image.jpg',2),(34,'Кадел (Cadel)','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах і супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, але в умовах спеки потребує регулярного поливу для збереження здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди великі, масою (150-160г.), подовжено-конічної форми, одномірні. Шкірочка щільна, глянцева, рубіновий рум\'янець на всю поверхню плоду. М\'якоть жовта, середньої щільності, в процесі зберігання стає пухкою, соковита, кисло-солодка, з сильним ароматом, доброго смаку. Дозрівають плоди - 15-30 вересня. Зберігаються до грудня. Збір врожаю вибірковий, в 2-3 етапи. При перезріванні смакові якості плодів знижуються. Стійкість до грибкових хвороб висока. Імунний сорт.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i4f589b4ed067461b/version/1676806123/image.jpg',2),(35,'Кальвіль Дюкена (Calville Duguesne)','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах і супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, але в умовах спеки потребує регулярного поливу для збереження здоров\'я дерева.','Садівництво','Дерево сильноросле. Плоди великі, масою (180-220г.), широко-усічено-конічної форми, з п\'ятьма ясно вираженими ребрами в області носика. Шкірочка запашна, на дотик жирна, тонка, але щільна, світло-жовта, вся всіяна темними точками різного калібру; сонячний бік плода іноді забарвлений в яскраво-рожевий колір. М\'якоть жовтувато-біла, середньої щільності, ніжна, соковита, кисло-солодка з тонким цукерковим ароматом, відмінного смаку. В процесі зберігання м\'якоть стає пухкою. Дозрівають плоди в середині вересня. Схили до осипання. Стійкість до грибкових хвороб висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/ic958a5c3823f2e26/version/1676806461/image.jpg',2),(36,'Кандиль синап','ереднього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і легких піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +35°C, але в умовах спеки потребує регулярного поливу для збереження здоров\'я дерева.','Садівництво','Дерево сильноросле. Плоди середнього та вище середнього розміру, масою (125-160г.), подовжено-циліндрової форми, з декілька конічною верхівкою.Шкірочка гладенька, глянцева, помірно жирна на дотик, в період знімальної зрілості світло-зелена, пізніше - світло-жовта, покрита яскравим червоно-рожевим рум\'янцем на більшій частині поверхні плоду, покрита численними, світло-зеленими підшкірними крапками і сизим нальотом. М\'якоть біла, ніжна, соковита, кисло-солодка, відмінного смаку. Кращі запилювачі: Сари Сінап, Розмарин білий, Банан зимовий, Аврора кримська. В умовах Криму знімальна зрілість плодів настає - 1-10 вересня, споживча - в жовтні. Яблука зав\'язуються добре, по 2-3, іноді 3-4 на одному плодовому утворенні. На дереві тримаються слабо, при вітрі легко обсипаються. У холодильнику при температурі + 2°С зберігаються до кінця січня. Стійкість до парші та борошнистої роси середня. Транспортабельність плодів середня.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i9a1dfe3173bf0bec/version/1676738456/image.jpg',2),(37,'Кармін','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак при високих температурах потребує регулярного поливу для підтримання здоров\'я дерева та врожайності.','Садівництво','Дерево середньоросле. Плоди великі, масою (170-220г.), мах - (250-280г.), кулясто-бочковидної (кулясто-конічної) форми, одномірні. Шкірочка зелено-жовта, покрита яскравим карміновим рум\'янцем на більшій частині поверхні плоду. М\'якоть жовтувата, середньої щільності, ароматна, кисло-солодка, відмінного смаку. Дозрівають плоди - 20 серпня - 10 вересня. Перед дозріванням схильні до осипання. Стійкість до грибкових хвороб висока. Імунний сорт.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i5d9b41262d917f03/version/1676539004/image.jpg',2),(38,'Мінкар','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах і супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак за умов спеки потребує регулярного поливу для підтримки здоров\'я дерева.','Садівництво','Дерево слаборосле. Плоди середньої величини, масою (120-150г.), мах - (180г.), округло-подовжено-конічної форми, декілька скошені, з слабо горбистою поверхнею. Шкірочка тонка, ніжна, помірно масляниста, покрита восковим нальотом, основне забарвлення в період знімальної стиглості - біло-зелене, споживчої - зеленувато або світло-жовте, покривне - у вигляді червоного розмитого рум\'янцю слабкої інтенсивності на сонячній стороні плоду. Підшкірні точки нечисленні, середніх розмірів, білі, слабо помітні. М\'якоть біло-зелена, середньої щільності, дрібнозерниста, хрустка, соковита, аромат середній, кисло-солодка, десертного доброго смаку. Кращі запилювачі: Айдаред, Ред Делішес, Світанок, допустимі - Голден Делішес, Флоріна. Дозрівають плоди - 15-30 вересня, споживча - жовтень. Зберігаються плоди, не втрачаючи смакових якостей, до січня. Стійкість до парші середня, борошнистої роси висока. Транспортабельність плодів хороша.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i484230655fa62eef/version/1676974102/image.jpg',2),(39,'Монастирське осіннє','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.\n','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, але при високих температурах потребує регулярного поливу для підтримки здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди великі, масою (190г.), кулясто-конічної або циліндричної форми, одномірні. Шкірочка біло-жовта з штрихуватим або розмитим яскраво-червоним рум\'янцем на сонячній стороні плоду. М\'якоть кремово-зелена, щільна, соковита, ніжна, кисло-солодка, з пряним ароматом, відмінного смаку. Стійкість до грибкових хвороб висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i70e699e35a546cf8/version/1676973813/image.jpg',2),(40,'Ред Пешн (Red Passion)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак в умовах спеки потребує регулярного поливу для підтримки здоров\'я дерева.','Садівництво','Дерево слаборосле. Плоди середнього розміру, масою (120-150г.), кулястої форми. Шкірочка темнувато-червона з точками і смугами. М\'якоть рожево-червона з білими прожилками, щільна, соковита, ароматна, солодка з легкою кислинкою, відмінного смаку і ягідним післясмаком. Містить велику кількість антиоксидантів. М\'якоть на повітрі не темніє і не втрачає свого кольору навіть після термічної обробки. Дозрівають плоди - 5-15 вересня. Зберігаються у сховищі до листопада. Під час зберігання смакові якості плодів поліпшуються.Стійкість до грибкових хвороб висока. Транспортабельність плодів хороша.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i0b6aebc01bf48d52/version/1677493976/image.jpg',2),(41,'Одіссо (Odysso)','великі, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах і супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак при високих температурах потребує регулярного поливу для запобігання перегріву дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру і великі, масою (150-200г.), округло-довгастої форми. Шкірочка яскраво темно-червона. М\'якоть червона, з білими прожилками, щільна, хрустка, соковита, ароматна, солодка з кислинкою, відмінного смаку. М\'якоть на зрізі не окислюється. Квітки червоні. Дозрівають плоди - 20 вересня - 10 жовтня. Зберігаються в сховищі - 3 місяці, в холодильнику з контролем температури - 4-5 місяців. Погано переносять низьку температуру при зберіганні. Стійкість до парші висока, до борошнистої роси середня. Транспортабельність плодів хороша.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i6d679194b188fb60/version/1677148844/image.jpg',3),(42,'Опал (Opal)','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +35°C, але при високих температурах потребує регулярного поливу для збереження здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (150-170г.), округлої форми, без ребристості. Шкірочка гладенька, блискуча, досить груба, без тенденції до оржавленості, золотисто-жовта, з легким помаранчевим рум\'янцем на сонячній стороні плоду. М\'якоть жовта, щільна, хрустка, соковита, солодка, з тонким ароматом, солодка, відмінного смаку. Кращі запилювачі: Еверест. Знімальна зрілість  плодів - 1-10 жовтня, споживча - з листопада до квітня. У холодильнику зберігаються 6 місяців. Під час зберігання не в\'януть, не стають кашоподібними. Імунний до парші, борошнистої росою не уражується. Транспортабельність плодів хороша.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i6b9f0e17c0e53f21/version/1677149586/image.jpg',3),(43,'Оріон','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +32°C, але в умовах спеки потребує регулярного поливу для підтримання здоров\'я дерева.','Садівництво','Дерево середньо- або сильноросле. Плоди великі, масою (180-260г.), округло-конічної форми, одномірні. Розміщені плоди по-одиночці, не потребують проріджування. Шкірочка світло-зелена, пізніше стає жовтою з невеликим рум\'янцем. М\'якоть жовта, щільна, хрустка, соковита, солодка з легкою кислинкою, доброго смаку. Кращі запилювачі: Місяць, Розелла, Ред Топаз, Гренні Сміт, Джеймс Грів, Джонатан, Мелроуз. Дозрівають плоди - 1-10 жовтня, споживання - грудень. Під час зберігання жовтіють, з\'являється легкий рум\'янець. У сховищі зберігаються до березня. При перезріванні не схильні до обпадання. Стійкий до грибкових хвороб. Товарність і транспортабельність плодів високі.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i4280b46a3567ea38/version/1677149518/image.jpg',3),(44,'Орнамент','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.\n','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак потребує регулярного поливу за високих температур для підтримки здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди вище середнього розміру, масою (170-200г.), округло-конічної форми, широко-ребристі. Лійка середньої глибини і ширини. Шкірочка товста, еластична, суха, зеленувато-жовта. М\'якоть кремова, середньої щільності, дрібнозерниста, соковита, кисло-солодка, доброго смаку. Кращі запилювачі: Айдаред, Аскольда, Радогость, Едера, Скіфське золото, Чемпіон. Знімальна зрілість плодів - 20-30 вересня, споживча - на початку листопада. Зберігаються в холодильнику до кінця січня. Стійкість до борошнистої роси висока, в роки з підвищеною вологістю повітря ураження плодів і листя паршею середня. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/ie93911e56ab02231/version/1677149056/image.jpg',3),(45,'Пілот','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +35°C, однак потребує регулярного поливу при високих температурах для підтримки здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (115-145г.), одномірні, подовженої, кунічно-конічної форми, з горбистій верхівкою. Шкірочка середньої товщини, щільна, еластична, гладенька, блискуча, світло-зелена, вкрита помаранчево-червоним розмито-смугастим рум\'янцем майже по всій поверхні плоду. М\'якоть біла, щільна, соковита, дрібнозерниста, із середнім ароматом, кисло-солодка, доброго смаку. Найкращі запилювачі: Айдаред, Пінова, Ремо, Ревена, Ельстар. Дозрівають плоди - 1-10 жовтня. У холодильнику зберігаються до квітня-травня. При зберіганні можуть уражуватись підшкірною плямистістю. Стійкість до грибкових хвороб вище середньої. Уражається бактеріальним опіком. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/iba176d5f8ac92a6b/version/1677331047/image.jpg',3),(46,'Пінк Леді (Pink Lady)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -20°C, однак може бути чутливим до сильних морозів, тому в холодних зонах потребує додаткового захисту.\nМаксимальна плюсова температура: переносить температури до +35°C, але в умовах спеки потребує регулярного поливу для підтримки здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру і великі, масою (140-190г.), округло-конічної форми, трохи асиметричні. Шкірочка тонка, жовто-зелена, покрита рожево-червоним рум\'янцем на 50-80% поверхні плоду і підшкірними крапками. М\'якоть біла, щільна, сколююча, хрустка, соковита, кисло-солодка, відмінного смаку. Кращі запилювачі: Голден Делішес, Гала. Дозрівають плоди - 20 жовтня - 10 листопада. Зберігаються в холодильнику до квітня-травня. При зберіганні зберігають свої товарні і смакові якості. Рано зняті плоди при зберіганні уражаються засмагою шкірки. Для отримання високотоварних плодів, необхідно сильно нормувати врожай. Стійкість до грибкових хвороб середня. Дуже сприйнятливий до парші, борошнистої росою уражується слабо. Вимагає захисту від парші. Транспортабельність плодів хороша.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i01c7463a1bb5ce51/version/1677150337/image.jpg',3),(47,'Пінова','середнього розміру, темно-зелені, овальні, з легким блиском.',' сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.\n','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, але при високих температурах потребує регулярного поливу для підтримання здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середнього та вище середнього розміру, масою (150-170г.), одномірні, кулясто-конусно-яйцевидної форми, з досить вузькою верхівкою. Шкірочка тоненька, щільна, гладенька, слабо блискуча, суха, зеленувато-жовта, вкрита помаранчево-червоним штрихувато-розмитим рум\'янцем на 60-70% поверхні плоду, і середньою кількістю великих і середніх, бежевих добре помітних великих і середнього розміру підшкірних цяток з опробковілим центром. М\'якоть жовтувато-кремова, дуже щільна, ламка, соковита, з приємним ароматом, кисло-солодка, карамельного відмінного смаку. Найкращі запилювачі: Аскольда, Гала, Глостер, Голден Делішес, Айдаред, Мелроуз. Чемпіон. Знімальна зрілість плодів настає - 20 вересня - 10 жовтня. При недбалому зборі плодів на них можуть з\'явитися вм\'ятини від пальців, що знижує їх товарність. У холодильнику зберігаються близько 8 місяців (до квітня-травня), не відчуваючи фізіологічних захворювань. До закінчення зберігання не втрачають соковитості, консистенції м\'якоті і в\'януть менше, ніж яблука Голден Делішес. Стійкість до грибкових хвороб висока, сприйнятливість до бактеріального опіку середня. Товарність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i2d9e6d3cbcf185f3/version/1677327304/image.jpg',3),(48,'Піруєт (Pirouette)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах і супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, але в умовах спеки потребує регулярного поливу для підтримання здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди середнього розміру і великі, масою (200-220г.), плоско-кулястої форми, одномірні, вирівняні, симетричні. Шкірочка гладенька, без оржавленості, жовтувато-зелена, вкрита яскравим помаранчево-червоним рум\'янцем на 50-80% поверхні плоду. М\'якоть жовта, щільна, сколююча, соковита, ароматна, кисло-солодка, відмінного смаку. Дозрівають плоди - 20 вересня - 10 жовтня, споживання - листопад - березень. Зберігаються в холодильнику 4-5 місяців. Стійкість до грибкових хвороб вище середньої. Транспортабельність плодів відмінна.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i00419ff4b750aed3/version/1677331519/image.jpg',3),(49,'Райка','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.\n','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -28°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак при високих температурах потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (140-180г.), мах - (200г.), одномірні, плоско-кулястої форми. Шкірочка світло-жовта, вкрита темнувато-червоним рум\'янцем на більшій частині поверхні плоду. М\'якоть жовта, середньо зерниста, соковита, ароматна, кисло-солодка, відмінного смаку. Хороший запилювач для інших сортів яблук. Дозрівають плоди - 1-10 жовтня. Зберігаються в холодильнику до 6 місяців. Стійкість до грибкових хвороб висока. Імунний до парші та борошнистої роси. Транспортабельність плодів відмінна.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/ifbe63b32cc68fa0a/version/1677745519/image.jpg',3),(50,'Раку-Раку (Фуджі)','великі, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -20°C, однак в умовах холодних зим може потребувати додаткового захисту.\nМаксимальна плюсова температура: переносить температури до +35°C, однак потребує регулярного поливу за високих температур для збереження здоров\'я дерева.','Садівництво','Дерево середньоросле. Плоди великі, масою (200-250г.), витягнуто-циліндричної форми. Шкірочка гладенька, злегка блискуча, жовто-зелена, вкрита розмитим рожево-червоним рум\'янцем по всій поверхні плоду. М\'якоть біла, щільна, ніжна, соковита, солодка, відмінного смаку. Дозрівають плоди - 1-10 жовтня. Зберігаються у сховищі до березня, в холодильнику - до квітня-травня. Стійкість до борошнистої роси і парші середня.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i4716669f9460ea51/version/1677746370/image.jpg',3);
INSERT INTO `sorts` VALUES (51,'Рамбур подільський','середнього розміру, темно-зелені, овальні, з легким блиском.',' сорт добре росте на родючих суглинках, чорноземах і супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів, де є помірна вологість.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +35°C, однак в умовах спеки потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево сильноросле. Плоди великі і дуже великі, масою (240-523г.), кулястої форми, зі зрізаними полюсами і з тупими ребрами по всій висоті. Шкірочка товста, груба, гладенька, блискуча, злегка жирна, зеленувато-жовта, вкрита темнувато-червоним розмито-крапчатим рум\'янцем на сонячній стороні плоду. М\'якоть біла, з зеленцею, ніжна, соковита, трохи пряна, кисло-солодка, посереднього смаку. Знімальна зрілість плодів настає - 20 вересня - 10 жовтня, споживання - жовтень. Слабо тримаються на дереві, сильно обпадають у міру дозрівання. Зберігаються у сховищі до лютого. Стійкість до парші середня, до борошнистої роси висока. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i683ce11a327e9385/version/1677746795/image.jpg',3),(52,'Ревена','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C.\nМаксимальна плюсова температура: переносить температури до +35°C, однак при високих температурах потребує регулярного поливу для запобігання перегріву.','Садівництво','Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i06fbc9852b266e66/version/1677747177/image.jpg',3),(53,'Ред Боскоп','великі, темно-зелені, овальні, з матовим блиском.',' сорт добре росте на родючих суглинках, чорноземах і супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -30°C, що робить його підходящим для більш холодних регіонів.\nМаксимальна плюсова температура: переносить температури до +30°C, однак при високих температурах потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево середньоросле. Плоди великі, масою (200-260г.), кулястої форми. Шкірочка жовта, вкрита темнувато-червоним розмитим рум\'янцем з невеликою оржавленністю. М\'якоть біла, дуже щільна, хрустка, солодка з кислинкою, ароматна, гарного смаку. Дозрівають плоди - 20-30 жовтня. Зберігаються у сховищі до квітня-травня. В процесі зберігання смакові якості плодів поліпшуються. Під час зберігання плоди схильні до в\'янення. Стійкість до грибкових хвороб вище середньої. Транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i6197223fca6e29b9/version/1677747735/image.jpg',3),(54,'Ред Девіл (Red Devil)','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак при високих температурах потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (140-180г.), плоско-кулястої форми, одномірні. Шкірочка карміново-червона. М\'якоть рожево-червона з білими прожилками, дрібнозерниста, соковита, солодка, доброго смаку. Дозрівають плоди - 20-30 вересня. Зберігаються в сховище - 2-3 місяці. При зберіганні набирає полуничний смак. Стійкість до грибкових хвороб висока. Стійкий до парші.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i68b5131a272b7bc1/version/1677748172/image.jpg',3),(55,'Ред Кап Валтод (RED CAP Valtod)','середнього розміру, темно-зелені, овальні, з помірним блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак за високих температур потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево середньо- або сильноросле. Плоди великі, масою (180-220г.), зрізано-конічної (видовженої) форми, ребристі, одномірні. Шкірочка блискуча, щільна, еластична, темно-червона, рівномірно забарвлена по всій поверхні плоду, з білими підшкірними крапками. Фарбуються плоди дуже рано - за кілька тижнів до їх повного дозрівання. М\'якоть біла, щільна, хрустка, середньої соковитості, солодка з кислинкою, доброго смаку. Дозрівають плоди - 20 вересня - 10 жовтня. Споживання - листопад. Зберігаються у сховищі - 5-6 місяців. Стійкість до грибкових хвороб висока. Товарність і транспортабельність плодів висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i92229a0c1233943f/version/1677749372/image.jpg',3),(56,'Ред Кетті','середнього розміру, темно-зелені, овальні, з легким блиском.',' сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак за високих температур потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево слабо- або середньоросле. Плоди середнього розміру, масою (120-150г.), кулястої, злегка видовженої форми. Шкірочка тоненька, щільна, карміново-червона. М\'якоть рожево-червона, середньої щільності, соковита, аромат середній, кисло-солодка, відмінного смаку. Дозрівають плоди - 20-30 вересня. Зберігаються в сховище - 2-3 місяці. В лежці протягом 3-4-х тижнів смакові якості плодів поліпшуються. Стійкість до грибкових хвороб висока. Товарність і транспортабельність плодів високі. Не вимогливий до умов вирощування.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i3351da1fcf915749/version/1677749805/image.jpg',3),(57,'Редкрофт (Redkroft)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних і піщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -20°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак за високих температур потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево середньоросле. Плоди середнього розміру, масою (120-160г.), мах - (200г.), плоско-кулястої форми, одномірні. Шкірочка темно-малиново-червона по всій поверхні плоду з білими дрібними крапками. М\'якоть кремова, щільна, хрустка, соковита, ароматна, кисло-солодка, відмінного десертного смаку. Дозрівають плоди - 20-30 вересня. Зберігаються в сховищі - 4-5 місяців. Перед дозріванням плоди схильні до осипання. Стійкий до парші.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i2743816e3bac794a/version/1677750259/image.jpg',3),(58,'Ред Мун (Red Moon)','середнього розміру, темно-зелені, овальні, з глянцевим блиском.',' сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.\n','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -20°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак при високих температурах потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево середньоросле. Плоди великі, масою (180-250г.), округло-видовженої (бочковидної) форми. Шкірочка темно-червона з білими підшкірними крапками на всій поверхні плоду. М\'якоть рожево-червона, з білими прожилками, дрібнозерниста, щільна, середньої соковитості, кисло-солодка, доброго смаку. Дозрівають плоди - 20 вересня - 10 жовтня. Зберігаються у сховищі до березня. Плоди містять високий вміст антоцианінів.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i8d3399d1a19a6e8a/version/1677830854/image.jpg',3),(59,'Ред Джонапринц (Red Jonaprince)','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах, а також на супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак за високих температур потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево сильноросле. Плоди великі, масою (200-220г.), кулясто-видовженої форми, одномірні, симетричні. Шкірочка тоненька, блискуча, гладка, вся поверхня плоду вкрита інтенсивно розмитим, темно-карміновим (бордовим) рум\'янцем. Плоди дуже рано фарбуються і в роки зі сприятливими кліматичними умовами набувають насичений темно-бордовий колір. М\'якоть кремова, тверда, соковита, хрустка, ароматна, кисло-солодка, відмінного смаку. За вмістом цукру в плодах, перевершує основний сорт Джонаголд. Плоди мають високим вмістом антоціанів. Найкращі запилювачі: Еліза, Ельстар, Гала, Глостер, Голден, Айдаред, Лігол, Чемпіон, Еверест. Знімальна зрілість плодів - середина вересня. Занадто раннє знімання плодів призводить до втрати смакових якостей. Зберігаються в холодильнику до квітня, в звичайному підвалі до січня. Дозрілі плоди осипаються. Стійкість до парші, борошнистої роси, бактеріального опіку - середня, захворювань кори і деревини – низька. Транспортабельність плодів хороша.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i6c8a1dc897f8b4d0/version/1677832763/image.jpg',3),(60,'Ред Чіф (Red Сhief)','середнього розміру, темно-зелені, овальні, з легким блиском.','сорт добре росте на родючих суглинках, чорноземах і супіщаних ґрунтах з хорошим дренажем. Підходить для нейтральних і слабокислих ґрунтів з помірною вологістю.','Оптимальна температура: від +18°C до +24°C.\nМорозостійкість: витримує морози до -25°C.\nМаксимальна плюсова температура: переносить температури до +30°C, однак за високих температур потребує регулярного поливу для запобігання перегріву.','Садівництво','Дерево слабо- або середньоросле. Плоди дуже великі, масою (200-380г.), довгасто-конічної форми. Шкірочка зеленувато-жовта, вкрита смугастий яскраво-червоним рум\'янцем на всю поверхню плоду. Поверхня плоду вкрита густим напівпрозорим пруіновим нальотом. М\'якоть світло-кремова, щільна, середньої соковитості, солодка, трохи пріснувата, ароматна, хорошого смаку. Найкращі запилювачі: Ельстар, Глостер, Голден Делішес. Знімальна зрілість плодів настає в кінці вересня, споживча стиглість - в грудні. Зберігаються плоди 7-8 місяців. Стійкий до борошнистої роси і бактеріального опіку, до парші стійкість середня. Плоди схильні до гіркої плямистості, скловидність плодів, гнилі і парші. Транспортабельність плодів відмінна. Висока стійкість плодів до механічних пошкоджень.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i3b41671ce4743653/version/1677598618/image.jpg',3),(61,'NJO','Середні, витягнуті, гладкі, блискучі, край листя дрібнопилчастий.','Невибаглива до ґрунтів.','Середня морозостійкість, витримує до -35°C.','Садівництво','Дерево середньоросле. Плоди великі і дуже великі, масою (280-350г.), окремі плоди досягають маси (500-800г.), подовжено-широко-грушоподібної (лампочковидної) форми. Шкірочка жовта з невеликою оржавленністю (оржавленність проявляється у вигляді дрібних крапок, плям і штрихів), на сонячній стороні плоду спостерігається легкий рожевий рум\'янець. На деяких плодах рум\'янець може бути відсутнім. М\'якоть біло-кремова, щільна, без грануляцій, масляниста, ніжна, дуже соковита, ароматна, солодка, відмінного смаку. Дозрівають плоди - 20-30 серпня. При зберіганні не вспухають. Стійкість до грибних хвороб висока. Не уражується паршею.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i434f1fa59155f666/version/1669825294/image.jpg',4),(62,'Бере Жиффар','Листя світло-зелене, дрібне, подовжено-еліптичної форми з майже рівним, злегка хвилястим краєм. Черешок тонкий, середньої довжини.','Віддає перевагу пухким, родючим ґрунтам.','Морозостійкість середня; рекомендується вирощування в регіонах з м\'яким кліматом.','Садівництво','Дерево середньоросле. Плоди нижче середнього і середнього розміру, масою (60-100г.), правильної видовжено-грушеподібної форми, іноді з невеликою бугристістю, причому на великих плодах бугристість більш різкіша. Шкірочка тоненька, ніжна, в період знімальної зрілості - зеленувата, з жовтуватим відтінком, при повному дозріванні - жовто-зелена, на тіньовій стороні є велика кількість дуже дрібних зелених цяток, на сонячній стороні плоду вкрита яскравим червоно-помаранчевим розмитим рум\'янцем і безліччю темно-червоних великих крапок. М\'якоть біла, ніжна, тане, соковита, слабо ароматна, майже без кам\'янистих включень, солодка з легкою кислинкою, дуже смачна. Найкращі запилювачі: Віл\'ямс, Улюблениця Клапа, Малівчанка, Говерла, Конференція. Знімальна зрілість плодів настає 20-25 липня. Дозрівання неодномірне. Період споживання становить - 3-5 днів, вживаються тільки у свіжому вигляді, довго не зберігаються. До парші плоди практично стійкі, листя уражується паршею і білою плямистістю. Значно уражаються плоди плодовою гниллю.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/ifa3b3dbf419a4111/version/1669720829/image.jpg',4),(63,'Бере літня','Листя світло-зелене, подовжено-еліптичної форми з рівним або злегка хвилястим краєм.','Віддає перевагу пухким, родючим ґрунтам; потребує достатнього зволоження.','Висока зимостійкість; підходить для вирощування в різних регіонах України.','Садівництво','Дерево сильноросле. Плоди від середнього до великого розміру, масою (230-280г.), видовжено-грушеподібної форми. Шкірочка тоненька, в період знімальної зрілості - зеленувато-жовта, з сірими крапками, при повному дозріванні - світло-жовта. Частина плодів на сонячній стороні плоду може мати рожевий рум\'янець. М\'якоть біла, ніжна, тане, соковита, наполовину масляниста, приємного, кисло-солодкого смаку. Дозрівають плоди - 15 серпня, на 8-10 днів раніше, ніж сорт Улюблениця Клаппа. Знімати плоди з дерева необхідно за 8-10 днів до настання біологічної зрілості. Короткий термін споживання плодів. Паршею не уражується.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i6c5aa8ff6fdae901/version/1669459316/image.jpg',4),(64,'Бере Прекос Мореттіні (Butirra Precoce Morettini)','Листя світло-зелене, подовжено-еліптичної форми з рівним або злегка хвилястим краєм.','Віддає перевагу пухким, родючим ґрунтам; потребує достатнього зволоження.','Добра зимостійкість; підходить для вирощування в різних регіонах України.','Садівництво','Стійкість до грибкових хвороб середня. Уражується паршею і бактеріальним опіком. Потребує обробки антибактеріальними препаратами.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i16bb605cafe61114/version/1669796231/image.jpg',4),(65,'Богема','Листя темно-зелене, подовгувате, вузьке','	Нейтральний','Морозостійкість:	- 27 °C','Садівництво','Дерево сильноросле. Плоди великі, масою (180-250г.), витягнуто-коротко-грушеподібної форми. Шкірочка зелено-жовта, при повному дозріванні - насичено-жовта зі слабко помітним рожевим рум\'янцем на сонячній стороні плоду. М\'якоть біла, соковита, масляниста, солодка, з тонким ароматом, приємного десертного смаку. Дозрівають плоди - 20 липня - 10 серпня. Потребує своєчасного збирання врожаю в стадії технічної зрілості. На дереві швидко перестигають. Стійкість до грибкових хвороб вища за середню. Помірно стійкий до бактеріального опіку.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i296178f5384a53c4/version/1669461056/image.jpg',4),(66,'Лісова Красуня','Темно-зелений','Нейтральний','Морозостійкість:	- 25 °C','Садівництво','Літній сорт. Плоди середніх та великих розмірів 170 – 220 гр, класичної грушоподібної форми. Шкірка тонка, щільна, трохи шорстка. М\'якуш жовтувато-білий, ніжний, соковитий, маслянистий, кисло-солодкий, високих смакових якостей.','https://kievsad.com.ua/sites/default/files/styles/webp/public/product/type-tree/2024-05/lesnaya_krasavica_0.jpg.webp?itok=bj86Ab42',4),(67,'Ізольда','Темно-зелений','Нейтральний','Морозостійкість:	- 27 °C','Садівництво','Дерево середньоросле. Плоди середнього розміру і великі, масою (160-230г.), грушевидно-видовженної форми. Шкірочка зелена, при знімальній зреілості і жовта при вживанні, тоненька, гладенька, без оржавленності, на сонячній стороні плоду червоний румянець на 20%. М\'якоть кремово-біла, ніжна, соковита, масляниста, тане, ароматна. Смак гармонійниїй, солодкувато-кислий, дуже смачний. Найкращі запилювачі: Бере Арданпон, Васса, Деканка зимова,  Таврійська, Бере Боск, Десертна, Віл\'ямс літній, Улюблениця Клапа, Конференція, Гортензія, Ред Ауньон, Парижанка. Знімальна зрілість плодів - 20 липня - 10 серпня, вживання -  15 серпня. Плоди можуть зберігатись 1 місяць в холодильнику, але через 2-3 тижні зберігання погіршуються їх смакові якості. Паршею уражуєтьсяя незначно, бактеріальним опіком - сильно.','https://kievsad.com.ua/sites/default/files/styles/webp/public/product/type-tree/2024-07/1942.650%402x.jpg.webp?itok=rBmPTIY-',4),(68,'Улюблениця Клапа (Clapp\'s Favorite)','темно-зеленого кольору','До ґрунтових умов особливо невибагливий, але на легких ґрунтах починає плодоносити раніше, ніж на важких глинистих. Погано росте на вологих ґрунтах, слабо дренованих, засолених та з близьким заляганням галечникового шару. ','Зимостійкість та посухостійкість високі.','Садівництво','Дерево сильноросле. Плоди вище середнього розміру, масою (180-230г.), яйцевидно-витягнутої форми. Шкірочка гладенька, ніжна, жовто-зелена, при повному дозріванні – жовта, з густим яскравим малиновим рум\'янцем на сонячному боці плоду, майже без іржавості. Поверхня вкрита помітними дрібними підшкірними цятками. Іноді біля основи вершини є слабка оржавленість у вигляді невеликих цяток. М\'якоть біла, ніжна, таюча, дуже соковита, з легким ароматом, солодка, з легкою кислинкою, відмінного смаку. Найкращі запилювачі: Бере Жиффар, Вілямс, Лісова красуня, Олів\'є де Серр, Панна, Іллінка, Бере Боск, Бере Лігеля, Деканка зимова, Сен-Жермен. Знімальна зрілість настає  - 1-10 серпня, споживча зрілість – 15-30 серпня. Плоди до біологічної зрілості досить міцно тримаються на дереві, при дозріванні схильні до обсипання. Для цього сорту необхідно відводити місця, захищені від сильних вітрів. Слід знати, що надто раннє і надто пізнє збирання плодів негативно позначається на якості плодів. У зв\'язку з цим плоди слід знімати за 10 днів до настання зрілості. Лежкість плодів – 10-15 днів. Листя та плоди уражаються паршею. Стійкість до інших грибкових хвороб – середня. ','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/if934e7287b354165/version/1670967628/image.jpg',4),(69,'Оригінальна','зелене','До ґрунтових умов не вимогливий. ','Дерево зимостійке, посухо- і жаростійке. ','Садівництво','Дерево середньоросле. Плоди середнього та вище середнього розміру (150-200г), видовженно-грушеподібної форми, злегка ребристі. Шкірочка щільна, матова, в період знімальної зрілості - жовтувато-зелена з ніжним розмитим червонуватим рум\'янцем на освітленому боці плоду. Забарвлення плодів дуже привабливе. М\'якоть білувато-кремова, ніжна, дрібнозерниста, масляниста, соковита, з легким ароматом, без грануляцій, солодка з приємною кислинкою і легким пряним ароматом, дуже хорошого смаку. Знімальна зрілість плодів настає – 1-15 серпня, споживча – за тиждень. Плоди зберігаються до 10 днів, при перезріванні вспухають. Стійкість до грибкових хвороб висока. Паршею не уражується.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/id5dd39cfd1383883/version/1671608446/image.jpg',4),(70,'Сілк Кінг (Silk King)','зелене','До ґрунтових умов не вимогливий. ','Зимостійкість дуже висока. Витримують морози до -32-34 градусів.','Садівництво','Дерево середньоросле. Плоди великі, масою (200-240г.), мах - (350-400г.), груше видно-циліндричної форми. Шкірочка жовтувато-зелена, з рожевим рум\'янцем на сонячному боці плоду. М\'якоть біла, щільна, соковита, масляниста, ароматна, солодка з кислинкою, відмінного смаку. Дозрівають плоди – 20 липня – 10 серпня. Зберігаються у холодильнику до 3-х тижнів. Стійкість до грибкових хвороб середня.  ','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i0cbf1f040760aab0/version/1678470326/image.jpg',4);
INSERT INTO `sorts` VALUES (71,'Старкримсон (Starkrimson, Red Clapp\'s)','Темно-зелене','Маловимогливий до умов зростання.','Зимостійкість вища за середню. Витримує морози до -26-29 градусів. Посухостійкість середня.','Садівництво','Дерево середньоросле. Плоди середнього розміру і великі, масою (180-260г.), грушеподібної форми. Ефектно виглядають на дереві. Шкірочка тонка, але міцна, гладка, основне забарвлення - жовте, покривне забарвлення - майже повністю покритий, розмитий темно-бордовий рум\'янцем на всій поверхні плоду. М\'якоть світло-кремова, дрібнозерниста, соковита, тане, масляниста, з приємним специфічним ароматом, кисло-солодка, високих смакових якостей. Кращі запилювачі: Вільямс руж Дельбара, Вільямс, Іллінка, Бере Боск, Лісова красуня, Бере Лігеля, Конференція, Бере прекос Мореттіні, Тріумф Пакгама, Десертна, Таврійська. Знімальна й споживча стиглість плодів настає - 20 липня - 10 серпня. Плоди схильні до осипання при перезріванні. Збір плодів необхідно проводити за 10-15 днів до повного їх дозрівання, як тільки починає червоніти шкірка. Зберігаються недовго - 8-10 днів. У холодильнику можуть зберігається - 20-30 днів. При перезріванні м\'якоть плоду (загниває зсередини) мацерується. Стійкість до грибкових хвороб вища за середню. Стійкий до парші та термічного опіку листя.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/if55f7ae93472755c/version/1678369501/image.jpg',4),(72,'Весільна','зелене','	Нейтральний','Висока зимостійкість, посухостійкість','Садівництво','Дерево невисоке, не займає багато місця підходить і для маленьких садів, має округлу крону середньої густини. Плоди масою 180-200 г, одновимірні, правильної грушовидної форми, жовта з червоним забарвленням. М\'якуш ніжний, соковитий, маслянистий, ароматний, рожево-червоного забарвлення. Стійкість до парші. Термін збору плодів настає в другий - третій декаді серпня, а термін споживання - у вересні.','https://kievsad.com.ua/sites/default/files/styles/webp/public/product/type-tree/2024-01/%D0%92%D0%B5%D1%81%D1%96%D0%BB%D1%8C%D0%BD%D0%B0%202.jpg.webp?itok=1QF9BV3V',4),(73,'Груша Дюшес (Вільямс)','Світло-зелене','Сорт невимогливий до ґрунтових умов, проте краще росте на родючих, добре зволожених ґрунтах.  Дерева добре ростуть на родючих, зволожених грунтах. Дерева добре ростуть на родючих, зволожених грунтах. Дерева добре ростуть на родючих, зволожених грунтах.','Зимостійкість вище середньої','Садівництво','Дерево слабо- або середньоросле. Плоди від середньої до великої величини, масою 160-220 г, довгасто-грушовидної форми, із злегка горбистою поверхнею. Шкірка тонка, блискуча, спочатку ясно-зелена, при дозріванні - восково-жовта з дрібними сірими точками та іноді рудими плямочками. М\'якоть жовтувато-біла, ніжна, тануча, соковита, винно-солодка з мускатним ароматом. Для отримання врожаю необхідні сорти-запилювачі, такі як «Лісова Красуня», «Улюблениця Клаппа» та «Бере Боск». Деревам потрібно забезпечувати захист від вітрів, оскільки сорт чутливий до повітряної посухи. Паршею вражається в середньому ступені.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/dyushes-letnij-vilyams_1.jpg?itok=VORT1WdK',4),(74,'Кармен','Темно-зелене','Добре ростуть на родючих, легких ґрунтах, підходять сонячні ділянки.','Висока морозостійкість','Садівництво','Дерево середньоросле. Плоди великі середньою масою близько 200 г, покриті на 50% поверхні бордовим рум\'янцем. М\'якуш щільний, соковитий, дуже приємного смаку. Стійкий до основних захворювань. Найкращі запилювачі Вільямс Літній, Конференція.','https://posadka.com.ua/upload/resize_cache/iblock/bf7/700_700_131903e01863149be97e251a4ed38558f/bf76aa0e74325bebd63589f39450ee28.jpg',4),(75,'Лимонка','зелене','Не вибаглива до умов вирощування.','Висока морозостійкість груші','Садівництво','Дерево середньоросле. Плоди середнього розміру середньою масою 100 – 140 г, лимонно-жовті, м\'якоть білого кольору, солодка, приємного смаку. Стійкість до основних захворювань середня. Збирання врожаю у кліматичних умовах півдня України з перших чисел серпня. Кращі запилювачі: Вільямс Літній, Улюблениця Клаппа.','https://posadka.com.ua/upload/resize_cache/iblock/8a1/422_442_131903e01863149be97e251a4ed38558f/v94f2ia96ec302vqk8rirgfp86e5o1pf.jpg',4),(76,'Ред Сенсейшн','зелене','Добре росте і плодоносить на сонячних місцях, родючих дренованих ґрунтах.','Висока морозостійкість.','Садівництво','Дерево середньоросле. Плоди грушоподібної форми, великі, середньою масою 170-240 г., насиченої темно-червоного забарвлення, дуже привабливого зовнішнього вигляду. М\'якуш соковитий, маслянистий, без грануляцій, ароматний, солодкий з мускатним присмаком, гарного десертного смаку. Стійка до основних захворювань.','https://posadka.com.ua/upload/resize_cache/iblock/925/480_480_131903e01863149be97e251a4ed38558f/92596430ac7fa34c86790f73ba63308e.jpg',4),(77,'Санта Марія','зелене','Посадка рекомендується на сонячних ділянках, на родючих суглинних ґрунтах з регулярним поливом під час вегетації та плодоношення.','Висока морозостійкість.','Садівництво','Дерево середньоросле. Знімна зрілість настає у середині вересня. Плоди груші великі, масою 180-230 гр, подовжено грушоподібної форми, з симпатичним розмитим рожевим рум\'янцем. М\'якуш жовто-білий, соковитий, ніжний, маслянистий з відмінними смаковими характеристиками. Стійкість до парші висока. Для регулярної та високої врожайності необхідно забезпечити регулярне санітарне обрізування (кронування) дерева.','https://posadka.com.ua/upload/resize_cache/iblock/bf9/480_480_131903e01863149be97e251a4ed38558f/bf9589c376be98d2c1a88d95fb422706.jpg',4),(78,'Груша Бере Боск','зелене','До складу ґрунту дерево маловимогливе','Зимостійкість вища за середню. ','Садівництво','Дерево середньоросле. Плоди великі, масою 150-220 г, з високими, видовжено-грушоподібною формою. Шкірка тонка, жовтувато-коричневого забарвлення. М\'якуш білий або з кремовим відтінком, маслянистої консистенції, ніжний, таючий, дуже соковитий і солодкий, запашний, з мигдальним присмаком. Дозрівають плоди 5-15 вересня, до вживання придатні одразу. Лежкість середня 20-30 днів. Плоди транспортабельні, зав\'язуються парами та трійками, але міцно утримуються на дереві і навіть при дозріванні не обсипаються, дозрівають не одночасно. Сорт стійкий до основних захворювань, слабко уражається паршою.','https://posadka.com.ua/upload/resize_cache/iblock/e1f/453_453_131903e01863149be97e251a4ed38558f/e1fdac217096cbbdc094bf194a96b5ec.jpg',4),(79,'Вікторія','зелене','	Нейтральний','Сорт з високою морозостійкістю і посухостійкістю','Садівництво','Дерево середньоросле. Плоди великі, гарного товарного вигляду, середньою масою 240 - 270 гам, правильної грушоподібної форми, з гладкою поверхнею. Забарвлення - зелена з рожевим рум\'янцем. М\'якуш білий, ніжний з приємним ароматом, кислувато-солодкого смаку. Імунний до парші, плодоносний, хороша транспортабельність і тривала лежкість плодів. Найкращі запилювачі - Бере Боск, Бере Дюмон, Бере Клержо.','https://posadka.com.ua/upload/resize_cache/iblock/c0b/379_379_131903e01863149be97e251a4ed38558f/c0bc55fdf05a03832d76a8a3b23f83a8.jpg',4),(80,'Молдавська рання','зелене','з грунтів найкраще підходить чорнозем або сірий лісовий грунт','відмінна морозостійкість','Садівництво','Дерево середньоросле. Плоди середньою масою 110-150 г, овально грушоподібної форми, зелено-жовтого забарвлення з розмитим на сонячному боці засмагою. М\'якуш кремовий, соковитий, маслянистий, з приємним ароматом. Транспортабельність середня. Вирізняється високою стійкістю до захворювань. Найкращі запилювачі: Улюблениця Клаппа, Бере Жифар.','https://posadka.com.ua/upload/resize_cache/iblock/b21/535_535_131903e01863149be97e251a4ed38558f/b21fa6d9adaa8241d4c9df1b5af314b0.jpg',4),(81,'Маргарита Марілля','світло-зелене','Сорт маловимогливий до ґрунтових умов, але найкраще росте і плодоносить на родючих і досить зволожених ґрунтах. ','Зимостійкість середня','Садівництво','Дерево слаборосле. Плоди дуже великі, масою (350-460г.), мах - (600г.), широко-грушеподібні або у вигляді дзвіночка з поступовим звуженням до плодоніжки, як би усічені до верхівки. Поверхня горбиста, ближче до філіжанки - широкоребриста. Шкірочка гладенька, середньої товщини, міцна, не груба, ніжна, блискуча, в період знімальної зрілості плодів - зеленувато-жовта, при повному дозріванні - золотисто-жовта, зі слабким помаранчево-червоним розмитим або смугастим рум\'янцем на 1/3-1/4 частини плоду та невеликими іржавими плямами. Підшкірні цятки невеликі, світло-коричневі, слабо помітні. М\'якоть жовтувато-біла або майже біла, середньої щільності, крупнозерниста, майже без грануляцій, тане, соковита, солодка, з легким ароматом, гарного смаку. Найкращі запилювачі: Парижанка, Марія, Якимівська, Роксолана, Кримська медова, Десертна. Уражується паршею середньо. Знімальна зрілість плодів настає – 1-10 вересня, споживча – 20 вересня – 10 жовтня. Плоди необхідно знімати з дерева вчасно, не чекаючи повного їх дозрівання на дереві, коли їх м\'якоть набуває крупнозернистої консистенції, внаслідок чого погіршується якість. Зняті з дерева плоди зберігаються протягом 2-3 тижнів в звичайних умовах. За потреби плоди добре зберігаються в холодильнику – до листопада-грудня. ','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/ie8cdfc22770010f4/version/1671648544/image.jpg',5),(82,'Конференція','зелене','родючі, легкі ґрунти.','Відзначено хорошу стійкість до заморозків.','Садівництво','Дерево середньоросле. Плоди груші Конференція відрізняються великою видовженою формою, середня вага яких становить 250 - 350 грамів і більша. Шкірка жовтувато-зелена з невеликим рум\'янцем. М\'якуш відрізняється солодким, ніжним, ароматним і насиченим смаком. Молоді саджанці вимагають рясного поливу. Регулярне обрізування – ще одна умова для отримання великого врожаю. Дерева рекомендуємо садити на сонячних місцях, захищених від сильних протягів. У третій декаді вересня та у першій - жовтня збір урожаю. Не схильний до парші, стійкий до шкідників.','https://kievsad.com.ua/sites/default/files/styles/webp/public/product/type-tree/2024-01/%D0%9A%D0%BE%D0%BD%D1%84%D0%B5%D1%80%D0%B5%D0%BD%D1%86%D1%96%D1%8F.jpg.webp?itok=HXyXizoV',5),(83,'Бере Боск (Forelle, Beurre Bosc, Kaiser Alexander)','зелене','До ґрунтових умов сорт не вимогливий, добре росте і плодоносить при достатньому зрошенні на легких за механічним складом грунтах.','Слабо зимостійкий сорт. Посухостійкість сорту невисока.','Садівництво','Дерево середньоросле. Плоди середнього розміру і великі, масою (150-240г.), правильної, видовжено-темно-грушоподібної форми, проте на одному і тому ж дереві зустрічаються плоди, що відрізняються за формою, симетричні, зав\'язуються по одному, рідше по 2-3. Шкірочка тонка, в момент знімальної зрілості - жовтувато-коричнева, при повному дозріванні стає світло-коричневою, золотистого кольору, суцільно оржавлена, ніжна, шорстка, з дуже дрібними, густо розміщеними іржавими цятками. Іноді на сонячному боці з\'являється слабкий рум\'янець. М\'якоть біла або кремова, дуже соковита, солодка, ніжна, тане, без грануляції, масляниста, з багатим пікантним мигдальним смаком і пряністю, приємним ніжним ароматом, вище десертного смаку. Найкращі запилювачі: Бере Арданпон, Десертна, Якимівська, Віл\'ямс, Улюблениця Клапа, Марія, Золотиста, Смарагдова, Гранд Чемпіон, Родзинка Криму. Знімальна зрілість плодів в умовах Криму настає - 5-15 вересня. Тримаються плоди на дереві міцно, не обсипаються навіть при сильних вітрах. Дозрівання плодів нерівномірне. Зав\'язуються парами і трійками. У холодильнику зберігаються до січня, в звичайних умовах - до 30 днів. При зберіганні плодів в холодильнику різко знижуються їх смакові якості: м\'якоть втрачає властиву їй жирність, стає твердою і хрусткою. В умовах Криму, в сувору зиму 1984/85 р., коли температура повітря досягала -28-30 градусів,  дерева сильно постраждали (3-4 бали), а молоді дерева вимерзли повністю. Середньостійкий до парші та термічного опіку листя. Кліщем уражується регулярно. Плоди дуже люблять оси.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i404bb06d46ebd003/version/1669457068/image.jpg',5),(84,'Бере Гарді (Харді, Бере Геллерт, Beurré Hardy)','зелене','Сорт невимогливий до грунту, любить помірно вологий, легкий за механічним складом грунт. Віддає перевагу відкритим сонячним місцям.','Слабо посухостійкий сорт. Відрізняється середньою зимостійкістю, вимагає вологих захищених від вітру місць. Дорослі дерева досить зимостійкі, а молоді можуть підмерзати.','Садівництво','Дерево сильноросле. Плоди вище середнього розміру і великі, масою (150-250г.), овально-конічної форми, іноді широко-грушевидної або деканьковидної форми. Шкірочка товста, груба, шорстка на дотик, суха, легко оржавленна, при знімальній зрілості - сірувато-зелена, при повному дозріванні - золотисто-жовта, вкрита великою кількістю сірувато-рожевих цяток, іноді з легким рожевим рум\'янцем на сонячній стороні плоду. М\'якоть біла, тане, соковита, ніжна, масляниста, вино-солодка з дуже приємним мускатом в смаку, з легкою терпкістю, гарного десертного смаку. Найкращі запилювачі: Бере Арданпон, Бере Жиффар, Лісова красуня, Улюблениця Клапа, Жозефіна Мехельнська, Деканка зимова, Віл\'ямс, Бон-Луїз Авранш, Маріана, Бере Боск, Кіффер. Сорт не пошкоджується паршею. Термічним опіком листя уражаються (1,5-2 бали), а також уражується білою плямистістю. Знімальна зрілість настає в першій половині - середині вересня, споживча стиглість через 2-3 тижні після збору плодів. У звичайних підвалах плоди зберігаються 15-20 днів, в холодильниках 85-120 днів.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i2c20c110e5991ec3/version/1669461420/image.jpg',5),(85,'Бере Діль (Beurré Diel, Імперіал)','зелене','Вимогливий до грунтово-кліматичних умов. Кращими є теплі суглинки або супісчані чорноземи.','Досить морозостійким, здатним виносити -25-30° морози.','Садівництво','Дерево середньо- або сильноросле. Плоди великі, масою (190-270г.), на молодих деревах - окремі плоди досягають до (500-900г.), кулясто-грушоподібної або широко-грушоподібної форми, злегка нерівнобокі, декілька горбаті, розширені посередині, звужені до вершини. Шкірочка тоненька, але досить щільна, при зніманні плодів - зелена, при повному дозріванні - помаранчево-жовта із золотистим відтінком і великими ржавими цятками. На сонячному боці плоду іноді з\'являється барвистий яскравий рум\'янець, у полюсів оржавлення. М\'якоть біла, середньої щільності, наполовину тане, соковита, не надто ніжна, солодка, трохи гіркувата, іноді біля насіннєвої камери трішки зерниста, вино-солодка, доброго десертного смаку. У плодів, вирощених в невідповідних для сорту умовах - терпка. Найкращі запилювачі: Бере Арданпон, Бере Боск, Вілямс, Улюблениця Клаппа, Деканка зимова, Сен-Жермен. Як запилювач цей сорт не застосовується, так як у нього нежиттєздатний пилок. Дозрівають плоди в умовах Криму в середині вересня. У сховищі зберігаються до грудня, в холодильнику - до січня. Сезон споживання: листопад - перша половина грудня. Плоди зав\'язуються частіше поодинці, але на дереві тримаються недостатньо міцно, і при невеликому вітрі обсипаються. Відрізняється здоров\'ям, довговічністю, а також сильним і швидким ростом навіть на айвовій підщепі. Листя дуже чутливе до великої спеки і гарячого сухого вітра, і під впливом цих несприятливих факторів воно до кінця літа сильно обпалюється. Посухостійкість низька. На деревах, що ростуть на недостатньо зволожених (сухих) грунтах, плоди бувають досить дрібні, несмачні і обсипаються. На холодних, сирих (перезволожених) грунтах вони виходять водянистими і сильно уражуються паршею. Високі смакові якості плодів виявляються лише при сприятливих умовах вирощування і при повній зрілості плодів. При вирощуванні в несприятливих для сорту умовах з\'являється терпкість і кам\'янистість в плодах, що в значній мірі знижує їх якість, а також схильність до грибкових хвороб. Сильно уражується термічним опіком листя (в окремі роки ступінь ураження листя досягає 4 бали), в результаті чого листя чорніє і обсипається. Паршею уражується середньо-сильно.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i53c47d41db44e298/version/1669539633/image.jpg',5),(86,'Бере Дюрандо (Bere Durandо, Berre Durondeau)','зелене','На родючому, не сухому, правильно зрошуваному грунті добре вдаються плоди.','Зимостійкість середня. Молоді дерева до 6-7-ми років мають низьку морозостійкість, в більш старшому віці дерева витримують морози: -25-27 градусів.','Садівництво','Дерево середньоросле. Плоди великі і дуже великі, масою (200-350г.), окремі плоди досягають значних розмірів (до 600г.) - на айвовій підщепі, конусоподібної форми з легкої бугристістю, одномірні, красиві. Зав\'язуються частіше парами, іноді трійками і рідше – по одинці. Шкірочка гладенька, тоненька, нещільна, блискуча, темно-жовта із золотистим відтінком і блискучим карміново-червоним рум\'янцем на сонячній стороні плоду. Зрідка є незначна оржавленність плодів. Вся поверхня всіяна численними великими сірими цятками. М\'якоть біла, ніжна, тане, масляниста, соковита, солодка з легкою кислинкою, відмінного десертного смаку. Дозрівають плоди - 15-30 вересня. На дереві тримаються міцно. Зі збором врожаю не можна запізнюватися і треба приступати відразу ж, як тільки основний зелений фон шкірочки плодів почне танути, приймаючи жовтуватий відтінок, що буває вже в першій декаді вересня. Тоді процес дозрівання протікає не так швидко, плоди влежуються у другій половині вересня і зберігаються близько місяця, після чого починають \"вспухати\". На посередньому піщаному грунті, якщо не давати добрив, плоді виходять поганої якості. Стійкість до грибкових хвороб висока. Рідко і слабко плоди уражуються паршею.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/id3d594987974b0af/version/1669458241/image.jpg',5),(87,'Бере Люка (Олександр Люка, Бере Олександр Люка, Beurre Alexander Lucas)','зелене','Не вимогливий до умов вирощування.','Зимостійкість середня або вища за середню. В сильні морозні зими дерева можуть підмерзати.','Садівництво','Дерево середньоросле. Плоди великі, масою (200-400г.), овально-грушевидної або широко-яйцевидної форми. На насіннєвій підщепі спостерігається неоднорідність плодів, на айвовій підщепі - плоди однорідні. Красивий загальний вид плодів. Шкірочка гладенька, масляниста на дотик, запашна, лимонно-жовта, з багаточисельними сірими точками і дрібними плямами, біля лійки і причашечного заглиблення оржавленна, з червонувато-помаранчевим рум\'янцем на сонячній стороні плоду. М\'якоть кремова, майже біла, дуже ніжна, тане, достатньо масляниста, дуже соковита, пряна, солодка з легкою приємною кислинкою, гарного смаку. Найкращі запилювачі: Бере Боск, Віл\'ямс, Улюблениця Клапа, Жозефіна Мехельнська, Бере Клержо. Знімальна зрілість плодів настає - 15-30 вересня, споживання - жовтень-грудень. Дозрілі плоди в процесі зберігання не в\'януть, не вспухають. В сховищі відмінно зберігаються до  Нового року. Плоди міцно тримаються на дереві, не обсипаються. Стійкість до грибкових хвороб висока. Плоди паршею не уражуються. Квітки в період цвітіння сильно уражуються квіткоїдом.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/if518c85978457e7a/version/1669538752/image.jpg',5),(88,'Бере Суперфен (Beurré Superfin)','зелене','Вимогливий до свіжого, глибокого та родючого грунту, вимагає захищеного, але не сильно обігріваємого сонцем місця.','Зимостійкість середня.','Садівництво','Дерево середньоросле. Плоди середнього розміру і великі, масою (140-180г.), притупленно-конічної форми, іноді наближаються за формою до бергамотовідної (кулясті з невеликою шийкою). Шкірочка слабо запашна, гладенька, майже суха на дотик, досить товста, блискуча, золотисто-жовта, подекуди є іржа, яка більше нагромаджується в області обох полюсів. По всьому плоду розсіяні численні різнокаліберні сірі цятки. Сонячний бік плоду вкритий широким і густим карміново-червоним рум\'янцем. М\'якоть біла, жовта біля шкірочки, дуже ніжна, масляниста, тане, запашна, вельми соковита, дуже солодка з мускатним присмаком і пряністю, і тонкої кислотою в смаку, в інших випадках у цих плодів в надлишку розвивається кислота, яка дуже псує їх смак. Дозрівають плоди - 1-15 вересня. Після знімання необхідно плодам влежуваться близько 14 днів. Зберігаються не більше 1 місяця, приблизно до середини жовтня. На початок жовтня плоди вже перестигають. Зав\'язуються плоди поодинці, на дереві тримаються міцно, не обсипаються. Стійкість до грибкових хвороб висока. Слабо уражується паршею.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/if4391cadc0cc2a96/version/1669541607/image.jpg',5),(89,'Бланка (Blanka)','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока.','Садівництво','Дерево слаборосле. Плоди дуже великі, масою (300-500г.), в одиничних випадках досягають (800г.), видовжено-конічної форми. Шкірочка гладенька, зеленувато-жовта, при повному дозріванні - жовта, без оржавленості. М\'якоть біла, середньої щільності, масляниста, без грануляцій, соковита, ароматна, солодка з легкою кислинкою, відмінного смаку. Дозрівають плоди - 20 вересня - 10 жовтня. Зберігаються в звичайному сховищі до грудня-січня, в холодильнику до 6 місяців. Плоди під час зберігання не вспухають, не гниють, не зморщуються. Під час зберігання починають жовтіти, м\'якоть стає маслянистою. Міцно тримаються на дереві, не обсипаються. Стійкість до грибкових хвороб висока. Сорт слабко сприйнятливий до парші.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i7ba9a0cb84213a52/version/1669029754/image.jpg',5),(90,'Вересневе Дево','зелене','Сорт мало вимогливий до грунтово-кліматичних умов, але реагує на їх зміну якістю плодів','Зимостійкість висока: при зниженні температури до -20 градусів не спостерігалося пошкодження ні квіткових бруньок, ні річного приросту.','Садівництво','Дерево середньоросле. Плоди великі, масою (210-260г.), видовжено-грушеподібної форми. Шкірочка щільна, гладка, блискуча, в період знімальної зрілості - зелена, в період споживчої зрілості - солом\'яно-жовта, з яскравим темно-червоним рум\'янцем на більшій частині поверхні плоду. М\'якоть напівмасляниста, соковита, ніжна, без грануляцій, солодка, хорошого смаку. Знімальна зрілість плодів - 15 вересня, споживча стиглість - після 2-3 тижнів зберігання. Високостійкий до парші та інших грибкових хвороб.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/ib3a1041affb35043/version/1669983819/image.jpg',5);
INSERT INTO `sorts` VALUES (91,'Вижниця','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока.','Садівництво','Дерево сильноросле. Плоди великі, масою (240-300г.), мах - (350-370г.), правильної, грушоподібної форми, одномірні. Шкірочка середньої товщини, суха, в період знімальної зрілості - зелена, з легким рум\'янцем, з численними великими сірими підшкірними крапками, які переходять в невеликі плями, створюючи ефект повної оржавленості. При повному дозріванні плоди набувають яскраво золотаво-жовтий відтінок. М\'якоть кремова, дуже соковита, ніжна, масляниста, без грануляцій, з сильним мигдальним ароматом, кисло-солодка, високих смакових якостей. Кращі запилювачі: Говерла, Улюблениця Клаппа, Стрійська, Малівчанка, Конференція. Дозрівають плоди - 15-25 вересня, вживання плодів - жовтень-листопад. При тривалому зберіганні в холодильнику до січня-лютого не втрачають своїх смакових якостей. Плоди необхідно знімати з дерева завчасно, тому що перестиглі плоди довго не зберігаються і інтенсивно псуються. При зборі плодів - вони як камінь, але після їх дозрівання м\'якоть стає м\'якою, соковитою, смачною, як мед. Єдиний недолік плодів - це тверда шкірка. В умовах Полісся і Лісостепу України сорт слабо уражується паршею, сильно бактеріальним опіком.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i299ad8dd884317e3/version/1669110953/image.jpg',5),(92,'Генерал Леклерк','зелене','Добре росте на родючих, проникних ґрунтах, в захищених місцях.','Зимостійкість і посухостійкість вища за середню.','Садівництво','Дерево середньо- або сильноросле. Плоди великі, масою (120-150г.), мах - (220-300г.), видовжено-грушеподібної форми. Шкірочка щільна, товста, гладенька, жовто-коричнева, вкрита темно-червоним рум\'янцем на сонячній стороні плоду. М\'якоть кремова, масляниста, соковита, ніжна, тане, дрібнозерниста, солодка з легкою кислинкою, відмінного смаку. Найкращі запилювачі: Конференція, Віл\'ямс літній, Пасс Крассан, Гранд Чемпіон, Деканка дю Коміс. Знімальна зрілість плодів - 15-30 вересня, споживча стиглість через 2 тижні після знімання плодів. У звичайних умовах зберігаються - 30-45 днів, в холодильнику до лютого. Міцно тримаються на дереві, не обсипаються. Стійкість до парші середня, до бактеріального опіку висока, середньо або сильно сприйнятливий до моніальному опіку.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i511e5a095e4cd331/version/1669984419/image.jpg',5),(93,'Гранд Чемпіон','зелене','Сорт вимогливий до грунтово-кліматичних умов, потребує теплого і захищеного від вітрів місця, добре вологого грунту. ','Зимостійкість середня.','Садівництво','Дерево середньоросле. Плоди великі, масой (180-220г.), видовженно-грушевидної форми, слабо ребристі. Шкірочка тоненька, золотисто-оржавленна, всіяна дрібними яскраво-коричневими, малопомітними цятками. М\'якоть кремова, ніжна, соковита, масляниста, кисло-сладка, відмінного смаку. Найкращі запилювачі: Бере Арданпон, Бере Боск, Васса, Золотиста, Кримська зимова, Якимовська, Десертна, Лазурна. Знімальна зрілість плодів в умовах Криму настає - 20-30 вересня. Тримаються плоди на дереві міцно, але при пізньому зборі можуть обсипатись. В холодильнику зберігаються до кінця грудня. В процесі зберігання спостерігається підвялювання  плодів. Стійкий до парші. Термічним опіком листя уражується середньо. ','https://image.jimcdn.com/app/cms/image/transf/dimension=290x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i1380b58e287ba510/version/1669992954/image.jpg',5),(94,'Гурзуфська','зелене','Сорт мало вимогливий до грунтових умов.','Зимостійкість достатньо висока для Криму (в інших регіонах України середня).','Садівництво','Дерево слабо- або середньоросле. Плоди средньої або вище середнього розміру, масою (160-170г.), мах - (280г.), коротко-грушевидної або яйцевидної форми. Шкірочка тоненька, шероховата, суха на дотик, основне забарвлення плодів в період знімальної зрілості - жовтувато-зелена, при повному дозріванні – жовта, вкривне забарвлення – відсутнє, але іноді  проявляється у вигляді легкого рум\'янцю на сонячній стороні з багаточисельними оржавленними підшкірними цятками і плямами. Малопривабливий сорт груші. М\'якоть кремова, ніжна, соковита, масляниста, з легкою кислинкою і ароматом рози, відмінного смаку. Найкращі запилювачі: Кримські зорі, Васса, Бере Боск, Золотиста, Десертна, Лазурна, Вітчизняна, Якимівська, Ізумрудна, Марія. Знімальна зрілість плодів в умовах Криму настає - 1-10 вересня, практично співпадаяючи з вживанням в їжу. Тримаються плоди на дереві добре, але при пізньому зборі можуть обсипатись. В холодильнику плоди зберігаються до кінця грудня, в звичайних умовах - до листопада.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i8205ed9d921178fe/version/1670059457/image.jpg',5),(95,'Десертна','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока. В умовах Криму посухостійкість достатньо висока.','Садівництво','Дерево середньоросле. Плоди великі, середньою масою (240г.), мах – (430г.), коротко-грушовидної форми, з широко-плоско-кулястою, слабо ребристою вершиною і короткою тупоконічною основою, одномірні. Поверхня трішки горбата. Шкірочка тоненька, гладенька, міцна, суха на дотик, основне забарвлення в період знімальної зрілості - жовто-зелене, при повному дозріванні – золотисто-жовте, з легким рум\'янцем на сонячній стороні плоду. М\'якоть кремова, соковита, масляниста, без грануляцій, гармонічного, кисло-солодкого смаку, з приємною мигдалевою пряністю. Найкращі запилювачі: Золотиста, Деканка дю Коміс, Кримська зимова, Васса, Якимівська, Ізумрудна, Марія, Салгарська зимова. Знімальна зрілість плодів в умовах Криму настає з 20 по 25 вересня. Плоди міцно тримаються на дереві, не обсипаються. В холодильнику  зберігаються до кінця січня, не втрачаючи своїх високих товарних і смакових якостей. Фізіологічними хворобами під час зберігання не уражується. Висока стійкість до парші і термічного опіку листя. Навіть в епіфітотійні роки, коли ураження таких районованних сортів, як Бере Арданпон і Деканка зимова складало 3-4 бали, у сорта Десертна ураження паршею як плодів, так і листя не спостерігалось.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i7581a1322cb5a69c/version/1670068521/image.jpg',5),(96,'Дюшес  Ангулем','зелене','Вимогливий до грунтових умов, потребує в теплому, захищенному від холодних вітрів місці посадки. Свої смакові характеристики повністю розкриває на теплих і легких грунтах з достатнім зволоженням. На тяжких, глинистих і сирих грунтах плоди мають погані смакові якості.','Зимостійкість нижча за середню.','Садівництво','Дерево слабо- або середньоросле. Плоди великі, масою (200-300г.), мах - (500г.), кулясто-широко-грушовидної форми, з стиснутими боками і бугристою поверхнею. Плоди зав\'язуються по одинці. Шкірочка жовта, щільна, блискуча з великими плямами і цятками, з зеленим або золотистим відтінком, іноді з блідим рум\'янцем на сонячній стороні плоду. М\'якоть світло-кремова, соковита, ніжна, тане, солодка з легкою кислинкою, відмінного смаку. Смак дуже залежить від ґрунтових умов, в сухих ґрунтах з помірним поливом плоди отримують відмінний смак і аромат, а в сухих глинистих ґрунтах смак дуже портиться. Знімальна зрілість плодів настає - 10-20 вересня. Після збору плоди дозрівають - 15-20 днів, після чого використовують у свіжому вигляді або в кулінарних переробках. Зберігають плоди до грудня. Найкращі смакові якості мають плоди у жовтні-листопаді; при перезріванні плоди «вспухають». При передчасному зборі плоди в\'януть і погіршуються їх смакові характеристики при зберіганні. Стійкий до парші, відносно стійкий до бактеріального опіку. Листя декілька страждають від білої плямистості.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i1d72275230a0c65c/version/1670099370/image.jpg',5),(97,'Кавказ','зелене','Невибагливий до ґрунтових умов. ','Зимостійкість в умовах північної частини Лісостепу задовільна: пошкодження плодових бруньок при зниженні температури до -25,9 градусів склали 15%','Садівництво','Дерево середньоросле. лоди великі та дуже великі, масою (200-360г.), видовжено-грушеподібної, правильної форми, з горбистою поверхнею, одномірні. Шкірочка середньої товщини, масляниста, в період знімальної зрілості - зеленувато-жовта, при повному дозріванні – інтенсивно жовта, вкрита карміновим рум\'янцем на більшій частині поверхні плода. По всій поверхні плода розкидані дрібні сіро-зелені плями і цятки, добре помітні. М\'якоть біла, щільна, масляниста, тане, ніжна, дуже соковита, з легким ароматом, невеликою терпкістю, кисло-солодка, хорошого смаку. За своїми смаковими якостями поступається ряду сортів осіннього терміну дозрівання. Найкращі запилювачі: Говерла, Кучерянка, Конференція, Улюблениця Клапа, Вілямс, Корсунська. Споживча зрілість настає – 20 серпня – 10 вересня, за умов Києва – 1-15 вересня. Тривалість зберігання до 20 днів, у спеціальних сховищах – 1,5 місяці. Плоди потрібно знімати заздалегідь, тоді вони доходять у лежці (6-8 днів) до повного дозрівання, при цьому їх смак стає ще більш гармонійним. Стійкість до грибкових хвороб висока. Стійкість до парші висока. Уражується моніліальним опіком. ','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i5cabbd301fa8b252/version/1670753821/image.jpg',5),(98,' Кримські зорі','зелене','Сорт не особливо вимогливий до ґрунтових умов. ','Характеризується досить високою для умов Криму зимостійкістю.','Садівництво','Дерево середньо- або сильноросле. Плоди великі, масою (220г), мах - (310г), видовжено-грушоподібної форми, дуже привабливі на вигляд, особливо при повному дозріванні. Шкірочка тоненька, гладенька, суха на дотик, з численними малопомітними зеленими підшкірними цятками. Основне забарвлення в період знімання плодів – жовто-зелене, у період споживання – жовте, вкривне – у вигляді яскраво-червоного рум\'янцю на більшій частині поверхні плоду. М\'якоть кремова, соковита, тане, кисло-солодка, гарного смаку. Найкращі запилювачі: Десертна, Деканка зимова, Лазурна, Смарагдова, Родзинка Криму, Якимівська. Знімальна зрілість плодів в умовах Криму настає – 1-15 вересня. Тримаються плоди на дереві міцно, від сильного вітру не обпадають. У холодильнику за температури +2 градуси зберігаються до грудня. Стійкість до грибкових хвороб висока. ','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i599e1aa3d5eb29bb/version/1670882915/image.jpg',5),(99,'Великоплідна','зелене','Відрізняється невисокою вимогливістю до умов вирощування','Гарна зимостійкість. У несприятливі для перезимівлі роки відмічено слабке ушкодження штамбу (1 бал), основні гілки не ушкоджувалися. ','Садівництво','Дерево середньоросле. Плоди великі, масою (280г.), мах - (400-500г. і навіть 670г.), грушоподібні або широко-грушоподібні, з гладкою або слабо горбистою поверхнею, від місця найбільшого діаметру до чашечки – широко-ребристі, незважаючи на велику величину, досить міцно тримаються на дереві. Шкірочка тоненька або середньої товщини, в період знімальної зрілості - зеленувато-жовта, у споживчій зрілості - світло-жовта, ніжна, гладенька, суха на дотик, блискуча, іноді із золотистою засмагою на сонячному боці плоду. Підшкірні цятки зелені або світло-коричневі, середньої величини, численні, іноді розкидані невеликі іржаві плями по поверхні плоду. М\'якоть біла, щільна, соковита, масляниста, ніжна, кисло-солодка, зі слабким ароматом, високих смакових якостей. Знімальна зрілість плодів настає – 15 вересня, споживча – на початку жовтня, у холодильниках можуть зберігатися до січня. При перенесенні з холодильника в тепле приміщення плоди не буріють згори і не спухають. У звичайному приміщенні та при кімнатній температурі плоди зберігаються до січня. Стійкість до парші та бактеріального опіку листя досить висока.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i3848b15d029cb497/version/1670777663/image.jpg',5),(100,'Малевчанка','зелене','До умов зростання маловимогливе. ','Зимостійкість висока.','Садівництво','Дерево сильноросле. Плоди великі, масою (250-270г), окремі (350-450г) і навіть до 570г. (на айвововій підщепі), вирівняні, правильної грушеподібної форми, з гладкою поверхнею. Шкірочка тоненька, але міцна, в період знімальної зрілості – зеленувато-жовта, іноді з легким рум\'янцем, у споживчій зрілості – світло-жовта. По поверхні плоду рідко розкидані невеликі золотаво-іржаві плями. Підшкірні цятки дрібні, рідкі, світло-коричневі, майже непомітні. М\'якоть кремова, соковита, ніжна, таюча, кисло-солодка, з приємним слабким ароматом, високих смакових якостей. Знімальна зрілість плодів настає у другій, споживча зрілість – у третій декаді вересня протягом місяця. Дозрівають плоди одночасно, на дереві тримаються міцно. У холодильнику плоди зберігаються до середини-кінця листопада. Паршею і борошнистою росою уражується середньо, бактеріальним опіком листя уражується слабо. ','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i4f3fffa129359973/version/1671460209/image.jpg',5),(101,'Баронеса де Мелло (Beurré Van Mons, Cannelle de Van Mons)','зелене','Не вимогливий до умов вирощування.','Зимостійкість вища за середню або висока.','Садівництво','Дерево середньоросле. Плоди середньої величини і великі, масою (170-200г.), грушеподібної форми, горбисті. Шкірочка суха, декілька шорстка на дотик, тоненька, але щільна, лимонно-жовтого кольору. Нерідко цей основний фон майже не видно, тому що поверхню плоду маскує густа пелена золотисто-бурої ржавчини. М\'якоть запашна, жовтувато-біла, ніжна, тане, з невеликими грануляціями біля насіннєвої камери, соковита, ароматна, дуже солодка, з приємним мускатно-пряним смаком, за смаком нагадує ківі. Якщо грунт не підходить для даного сорту, то в м\'якоті розвивається надлишок кислоти і терпкості, тому плоди набувають неприємного терпкого смаку. Відмінний десертний сорт. Дозрівають плоди - 1-15 жовтня і висять на дереві до кінця листопада. Зав\'язуються парами і пучками. На дереві тримаються міцно, не обсипаються, перезрілі «вспухають». У звичайному підвалі зберігаються до січня. Стійкість до грибкових хвороб висока. Рідко уражується паршею.','https://image.jimcdn.com/app/cms/image/transf/dimension=168x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i3e5686f4a2febf83/version/1669641146/image.jpg',6),(102,'Бере Арданпон (Фердинанд)','зелене','До грунтів сорт пред\'являє досить високі вимоги. Найкраще вдається на родючих і теплих суглинних або нанесених ґрунтах, при достатній кількості тепла і вологи. Погано росте і плодоносить на вологих, холодних і важких грунтах, плоди виходять низьких якостей.','Сорт мало стійкий до великих знижень температури.','Садівництво','Дерево сильноросле. Плоди вище середньої величини або великі, масою (170-220г.), колокольчато-грушеподібної форми, з горбистою поверхнею. Шкірочка тоненька, щільна, гладка, матова, трішки жирна на дотик, в період знімальної зрілості - зелена, у споживчій зрілості - світло-жовта, з дрібними бурими цятками, іноді з рожевим рум\'янцем у вигляді легкої засмаги. М\'якоть біла, ніжна, тане, дуже соковита, масляниста, кисло-солодка, ароматна, відмінного десертного смаку. Найкращі запилювачі: Віл\'ямс, Лісова красуня, Деканка зимова, Бере Боск, Сен-Жермен, Пасс-Крассан. Сорт практично самобезплідний. Знімальна зрілість на півдні України в кінці вересня - початку жовтня, споживча стиглість настає на початку листопада. Тривалість зберігання до середини січня, в холодильнику до весни (230-250 днів). Плоди дозрівають неодночасно, до настання знімальної зрілості плоди досить міцно тримаються на дереві. Перетримувати плоди на деревах, не дивлячись на міцність прикріплення їх, не слід, так як після настання знімальної зрілості плоди збиваються навіть порівняно невеликими поривами вітру. Знімання плодів ведуть в 2-3 етапи. Урожайність сорту сильно коливається в залежності від умов зростання. Навіть в висококультурних, систематично зрошуваних садах Криму Бере Арданпон не всюди дає хороші врожаї. Сирих грунтів цей сорт не виносить. Уражується хворобами у сильному ступені: парша листя (максимальний бал) - 4, плодів - 4, ентомоспоріоз - 3, а також неодномірність плодів і значне варіювання їх за формою. Сорт вимагає рясного поливання, яке обумовлює якість плодів.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i4dc1542ae5ea3d0c/version/1669543880/image.jpg',6),(103,'Бере Клержо (Beurré Clairgeau)','зелене','М\'який клімат в зоні вирощування, зрошення та легкі грунти, які добре прогріваються - основні чинники, які визначають якість плодів цього сорту. На сухому грунті плоди не мають тих високих смакових якостей, яких вони досягають в хороших умовах.','Зимостійкість вища за середню.','Садівництво','Дерево слаборосле. Плоди великі і дуже великі, масою (150-250г.), мах - (600-800г.), середні плоди конічні або кулясто-конічної форми, частіше зігнуті в одну сторону, рівні, без ребер і горбів. Великі плоди видовжені, тупо-грушоподібної форми, горбисті. Форма плодів може змінюватися. Шкірочка матова, шорстка, товста, щільна, під час знімання - зелена, в період споживання - золотисто-жовта, на сонячній стороні плоду спостерігається яскравий карміновий рум\'янець, часто покриває плід до половини, а також по всій поверхні плоду усіяні сіро-бурі цятки і іржаві плями (особливо на полюсах), які часто переходять у сітку. Зустрічаються окремі екземпляри неоржавлені і незафарбовані. М\'якоть біла, ніжна, масляниста, тане, ароматна, соковита, солодка з легкою кислинкою, доброго смаку. Найкращі запилювачі: Улюблениця Клаппа, Десертна, Микола Крюгер, Лісова красуня. Дозрівають плоди - 20-30 вересня, споживання - через 20-30 днів. Зберігаються до грудня. Необхідно суворо дотримуватися термінів збору врожаю, не перетримуючи плоди на дереві. Тільки для плодів, які відлежалися, характерна масляниста смачна м\'якоть, яка тане в роті. Ближче до осені плоди не міцно тримаються на дереві і можуть обсипатися. Споживча зрілість плодів настає в листопаді, іноді вона зберігаються до грудня. При запізнення зі зніманням смак плодів погіршується. Стійкість до грибкових хвороб середня. Слабо стійкий до парші. Сильно уражуються плоди плодожеркою.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/if13adcba4a238e0c/version/1669460264/image.jpg',6),(104,'Васса','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока.','Садівництво','Дерево сильноросле. Плоди вище середнього розміру, масою (160г.), мах - (240-300г.), кулястої, правильної форми, симетричні, з широкоовальною вершиною і основою. Шкірочка гладенька, матова, суха на дотик, основне забарвлення в період знімальної зрілості - золотисто-жовте, покривне - у вигляді ніжного, легкого, рожевого рум\'янцю на сонячній стороні плоду. Румянец спостерігається на окремих плодах. Підшкірні крапки численні, добре помітні, сірі, дрібні. М\'якоть кремова, соковита, тане, дуже ніжна, масляниста, ароматна, відмінного, кисло-солодкого смаку, з приємною пряністю. Найкращі запилювачі: Золотиста, Бере Арданпон, Деканька зимова, Бере Боск, Вітчизняна, Таврійська, Смарагдова, Родзинка Криму, Марія, Якимівська. Дозрівають плоди в умовах Криму - 1-10 жовтня. Плоди краще збирати пізніше, але до сильних заморозків. Міцно тримаються на дереві, але при незначних осінніх заморозках міцність кріплення плодів до дерева слабшає. У сховищі зберігаються до січня, не втрачаючи своїх смакових якостей, в холодильнику до травня. Плоди потребують дозрівання при температурі +18-20° протягом 10-15 днів в грудні-січні і 5-8 днів в травні. Стійкість до термічного опіку листя висока. Листя і плоди стійкі до парші середньо. Грибковими хворобами в період зберігання плоди не уражуються.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i3f64c02e4e78b888/version/1669802515/image.jpg',6),(105,'Деканка зимова (Дюшес зимовий)','зелене','Грунти цьому сорту потрібні плодородні, легкі, глибокі і свіжі. На недостатньо плодородних, а також на сирих і холодних грунтах плоди дрібнішають, не розвивають необхідні сорту високі смакові якості, дерева швидко зношуються і старіють.','Слабка морозостійкість','Садівництво','Дерево середньоросле. Плоди великі, масою (160-300г.), бочковидної форми з бугристою поверхнею, при знімальній зрілості - зелені з незначним рум\'янцем на сонячній стороні плоду, в лежці стають - зеленувато-жовті з багаточисельними цятками. М\'якоть біла, ніжна, соковита, тане, ароматна, солодка з помірною кислинкою, відмінного смаку. Найкращі запилювачі: Бере Арданпон, Віл\'ямс, Улюблениця Клапа. Сорт дуже вимогливий до ґрунтів і клімату. Дерева гарно ростуть і дають плоди високої якості тільки в благодатних умовах вирощування. Навіть в Криму не в усіх садових районах цей сорт гарно вдається. Найкращі результати він дає на Південному березі Криму. Цей сорт потребує високих, теплих і гарно захищених місць, тому що його важкі великі плоди недостатньо міцно тримаються на плодушках. Ґрунти цьому сорту потрібні плодородні, легкі, глибокі і свіжі. При наявності цих умов дерева Деканки зимової гарно розвиваються, приносять високоякісні плоди і відмічаються довголіттям. При вирощуванні цього сорту, потрібно регулярно і своєчасно проводить зрошування. Період зрошення приходиться на 2 останніх літніх місяця або на першу половину вересня. Збирають плоди Деканьки зимової в Криму - 20 вересня - 1 жовтня. Знімальна зрілість плодів настає неодночасно. Щоб отримати плоди високої якості, не потрібно збирати плоди завчасно: чим пізніше будуть зібрані плоди, тим вони будуть смачніші. Великі плоди легко обсипаються при сильних осінніх вітрах. Зберігати плоди можна до початку літа наступного року, хоча дозрівання закінчується в грудні.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i68c2a26fbb552a27/version/1670332756/image.jpg',6),(106,'Жозефіна Мехельнська','зелене','Сорт не вимогливий до грунтових умов, але на плодородних, достатньо зволожених грунтах покращується якість плодів і збільшується їх розмір.','Морозостійкість висока – витримує зниження температури до -30-35°. Посухостійкість висока.','Садівництво','Дерево середньоросле. Плоди від дрібних до середнього розміру, масою (90-110г.), на айвовій підщепі (150-170г.), широко-тупоконічної форми, трішки бугристі, нерівнобокі, одномірні. Блюдце дрібне, вкрите бурою оржавленістю. Шкірочка тоненька, гладка, блискуча, в період знімальної зрілості – золотисто-жовта. По всій поверхні плоду розкидані сірі цятки і оржавлені плями, біля лійки спостерігається суцільна оржавленість. Деякі плоди на сонячній стороні плоду мають легкий рум\'янець. М\'якоть помаранчево-рожева, ароматна, дуже соковита, ніжна, тане, масляниста, без кам\'янистих включень, солодка з легкою кислинкою і мускатною пряністю, десертного смаку. В стані повної зрілості дуже смачна. Найкращі запилювачі: Стрійська, Конференція, Кучерянка, Улюблениця Клапа, Сен-Жермен, Лісна красуня, Бере Лігеля, Бере Боск, Бере Діль, Дюшес Ангулем. В свою чергу Жозефіна Мехельнська запилює Сен-Жермен, Кюре. Самобезплідний сорт, потребує запилювачі. Знімальна зрілість плодів настає  - 20 вересня - 10 жовтня, а іноді і пізніше, вживання після дозарювання плодів -  з листопада по січень. Зрілі плоди можуть довгий час зберігатись в сховищі до березня, не втрачаючи своїх смакових якостей. На дереві плоди тримаються міцно, не обсипаються.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i30594f55bbdb634a/version/1670401136/image.jpg',6),(107,'Золота осінь','зелене','Не вимогливий до грунтово-кліматичних умов.','Зимостійкість висока, витримує морози до -28-30°. ','Садівництво','Дерево слаборосле. Плоди великі, масою (250-310г.), конічної або тупо-яйцевидної форми, одномірні. Шкірочка тоненька, гладенька, суха, трішки оржавленна, в період знімальної зрілості - зеленувато-жовта, при повному дозріванні - золотисто-жовта з яскравим червоним румянцем на сонячній стороні плоду, з багаточисельними сірими підшкірними цятками. М\'якоть біла, соковита, масляниста, тане, гармонійного, кисло-солодкого смаку. Знімальна зрілість плодів настає - 1-15 жовтня, вживання - листопад. Зберігаються плоди в холодильнику до лютого-березня. Стійкий до парші і термічного опіку листя.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/i9d9903533aba474a/version/1670404018/image.jpg',6),(108,'Золотиста','зелене','Сорт мало вимогливий в умовах вирощування.','Зимостійкість і посухостійкість – високі.','Садівництво','Дерево в молодому віці – слаборосле. Плоди вище середньої величини, масою (160г.),  мах – (300-400г.), декілька неодномірні, кулясті або випукло-конічної форми. Шкірочка середньої товщини, гладенька, суха на дотик. Основне забарвлення в період знімальної зрілості зеленувато-жовте, вкривне – легкий рожевий рум\'янець на сонячній стороні плоду. М\'якоть кремова, середньої щільності, ніжна, масляниста, соковита, сладкувато-кислого смаку, відмінного смаку, с легким ароматом рози. Найкращі запилювачі: Деканка зимова, Васса, Бере Боск, Олів\'є де Серр, Вітчизняна, Бере Арданпон, Десертна, Таврійська, Таюча, Марія, Ізумрудна, Ізюмінка Криму, Якімовська, Бере Гарді, Добра Луїза, Маріана, Віл\'ямс, Улюблениця Клапа. Знімальна зрілість плодів настає - 20 вересня - 10 жовтня, вживання – грудень-січень. В сховищі плоди зберігаються - 100-120 днів, не втрачаючи своїх смакових якостей. В холодильниках при температурі +1-2° плоди зберігаються до кінця квітня. В період зберігання плоди грибними хворобами не уражуються. Після збору плоди потребують дозарювання при кімнатній температурі на протязі 10-15 днів. Після повного дозрівання плоди отримують відмінні смакові якості. Стійкість до парші – середня, до термічного опіку  - висока.','https://image.jimcdn.com/app/cms/image/transf/dimension=325x1024:format=jpg/path/s2bf7bf36b3cc98c5/image/ie787e853c7970bc2/version/1670596753/image.jpg',6),(109,'Ізумрудна','зелене','Сорт не вимогливий до грунтових умов','Зимостійкість висока. При зниженні температури до -28-30° ураження дерев не було і дерева дали гарний врожай.','Садівництво','Дерево середньоросле. Плоди великі і дуже великі, масою (250-280г.), бочковидної форми, одномірні, с горбистою поверхнею. Шкірочка суха, гладенька, міцна. Основне забарвлення плоду в період знімальної зрілості – зелене, при вживанні – яскраво жовте, покривне – на окремих плодах у вигляді легкого рум\'янцю. М\'якоть біла, щільна, соковита, тане, кисло-солодкого смаку. Найкращі запилювачі: Бере Арданпон, Васса, Деканка зимова, Якимівська, Марія, Бере Боск. Для даного сорту характерна самоплідність, але кращі результати дає перехресне запилення. Знімальна зрілість плодів в умовах Криму настає в жовтні, плоди необхідно збирати з дерева, як можна пізніше. Плоди міцно тримаються на дереві. Сорт не вимогливий до ґрунтових умов, але для нормального визрівання і отримання високої якості плодів, необхідно багато тепла і довгий вегетаційний період для даного сорту. Під насадження даного сорту груші необхідно відводити найбільш теплі і гарно освітлені сонцем місця. Швидкоплідний, десертний сорт, має стабільну врожайність, толерантний до парші і термічного опіку листя. Жаростійкий сорт.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i276c80e0d229f047/version/1670597972/image.jpg',6),(110,'Ізюминка Криму','зелене','Сорт не вимогливий до грунтових умов','Зимостійкість висока. Дерева при температуре -30° не мали значних уражень. Посухо- і жаростійкість – середня.','Садівництво','Дерево середньоросле. Плоди великі, масою - (230г.), мах – (450г.). тупояйце- або бочковидної форми. Шкірочка гладенька, середньої товщини, міцна, суха на дотик. Основне забарвлення в період знімальної зрілості – зеленувато-жовте, при вживанні – золотисто-жовте, вкривне –у вигляді яскравого румянцю на більшій частині плоду. М\'якоть кремова, середньої щільності, соковита, тане, кисло-солодка, гарного смаку. Найкращі запилювачі: Бере Арданпон, Деканка зимова, Васса, Кримська зимова, Золотиста, Марія, Таврічеська, Золота осінь. Знімальна зрілість плодів в умовах Криму - 15 жовтня. Сорт не вимогливий до ґрунтових умов, але для отримання високоякісних плодів необхідна велика кількість тепла і довгий вегетаційний період. Швидкоплідний сорт, висока стабільна врожайність, толерантний до парші і термічного опіку листя. Плоди міцно тримаються на дереві','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i683d84ed33220573/version/1670681876/image.jpg',6);
INSERT INTO `sorts` VALUES (111,'Киргизька зимова','зелене','Невибагливий до умов вирощування. ','Зимостійкість та посухостійкість високі. ','Садівництво','Дерево середньоросле. Плоди великі, масою (220-250г.), видовжено-яйцевидної або кубоподібної форми, одномірні. Форма плода непостійна, різноманітна, як і розмір плоду. Шкірочка жорстка, у знімальній зрілості – зеленувато-жовта, у споживчій зрілості – золотаво-жовта, вкрита яскравим червонувато-карміновим рум\'янцем на більшій частині поверхні плоду. М\'якоть кремова (світло-жовта), щільна, крупнозерниста, ароматна, трохи терпка, хрумка, соковита, солодка з кислинкою, посереднього смаку. Найкращі запилювачі: Вітчизняна, Смарагдова, Родзинка Криму, Олів\'є де Серр, Пасс Крассан, Золотиста, Бере Арданпон. Знімальна зрілість плодів в умовах Криму настає – 1-20 жовтня. Плоди міцно тримаються на дереві, не обсипаються. У звичайному підвалі плоди зберігаються до січня, у холодильнику – до квітня. Смак набирають під час зберігання. Споживаються з грудня до квітня. Стійкий до парші, термічного опіку листя та бактеріального опіку. ','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i2a5d5169b021bce7/version/1670883763/image.jpg',6),(112,'Кучерянка','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока.','Садівництво','Дерево сильноросле. Плоди великі, масою (220-290г.), широкогрушовидної або кубовидної форми, трішки бугристі. Шкірочка середньої товщини, щільна, в період знімальної зрілості світло-зелена, в період вживання - жовта, слабо блискуча, з легким золотистим або трішки рожевим загаром на сонячній стороні плоду. Підшкірні цятки дрібні, зелені або світло-коричневі, гарно помітні. На деяких плодах розкидані невеликі ржаві плями. М\'якоть біла, щільна, масляниста, тане, солодка з легкою кислинкою і слабким ароматом, з невеликою терпкістю біля шкірочки, практично без грануляцій, відмінного смаку. Найкращі запилювачі: Малівчанка, Конференція, Говерла, Стрійська, Придністрянка, Конкорд. Знімальна зрілість - 20-30 вересня, вживання - грудень. В холодильниках плоди можуть зберігатись до березня. При переміщені з холодильника в тепле приміщення не буріють зверху і не вспухають з середини. На дереві плоди тримаються міцно. Сорт стійкий до парші, бактеріального опіку листя, борошнистої роси, плямистості листя.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i2322411572bfbda9/version/1670666346/image.jpg',6),(113,'Маріана (Принцеса Маріана, Салісбура)','зелене','До ґрунтових умов не особливо вимогливий. ','На півдні України зимостійка, у північних областях зимостійкість середня.','Садівництво','Дерево сильноросле. Плоди середнього розміру, масою (100-120г.), мах - (130-170г.), грушоподібної форми, зі злегка горбкуватою поверхнею. Шкірочка жорстка, але дуже тонка, солом\'яно- або світло-жовтого кольору, з численними іржавими плямами; нерідко вся поверхня плоду суцільно оржавлена, з великими світло-сірими крапками, з буро-червоним рум\'янцем на сонячній сторону поверхні плоду. М\'якоть біла, ніжна, тануча, дуже соковита, кисло-солодка, терпкувата, гарного смаку. Дозрівають плоди – 20 серпня - 10 вересня, споживання – 15-30 вересня. Сприйнятливий до парші та ентомоспоріозу, плоди сильно уражуються моніліозом.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i4d0a4b3ef8531dc2/version/1671650724/image.jpg',6),(114,'Марія','зелене','Не вимогливий до умов вирощування.',' Зимостійкість висока.','Садівництво','Дерево слаборосле. Плоди великі і дуже великі, з масою (220г.), мах - (350г.), видовжено-грушоподібної форми, з гладкою поверхнею, одномірні.  Шкірочка середньої товщини або тоненька, гладенька, суха, основне забарвлення в період знімальної зрілості - жовтувато-зелене, в період споживання – золотисто-жовте, вкривне - яскравий червоно-кармінний рум\'янець на сонячному боці плоду, з багато чисельними дрібними зеленими і сірими підшкірними цятками. М\'якоть кремова, соковита, тануча, масляниста, відмінного, кислувато-солодкого смаку. Найкращі запилювачі: Гранд Чемпіон, Жанна Дарк, Якимівська, Десертна, Золотиста, Салгірська зимова. Знімальна зрілість плодів у Криму настає – 1-10 жовтня. У холодильнику плоди добре зберігаються до травня. Стійкість висока до парші та термічного опіку листя в умовах Криму.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i038bde3ad28af438/version/1671650492/image.jpg',6),(115,'Мліївська зимова','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока. ','Садівництво','Дерево сильноросле. Плоди великі, масою (180-200г.), видовжено-широко-грушоподібні, злегка горбисті. Шкірочка рівна, на дотик злегка «жирна», жовтувато-зелена, з легким рум\'янцем, з дрібними іржавими цятками, що зливаються в плями. М\'якоть жовтувато-біла, соковита, солодка, з приємною кислинкою, гарного смаку, дрібнозерниста. Знімальна зрілість плодів – 20 вересня – 10 жовтня, споживча зрілість – кінець грудня. Плоди зберігаються до квітня-травня, не втрачаючи своїх смакових якостей. Сорт стійкий до парші, нестійкий до білої плямистості. ','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i783fdff85f1fb8de/version/1671650254/image.jpg',6),(116,'Наталка','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока.','Садівництво','Дерево середньоросле. Плоди дуже великі, масою (300г.), мах – (450г.), правильної, грушоподібної форми, слабо горбисті, одномірні. Шкірочка тоненька, ніжна, масляниста. Основне забарвлення в період знімальної зрілості - зелене, покривне - легкий рум\'янець на сонячному боці плоду. М\'якоть біла, ніжна, дуже соковита, відмінного кисло-солодкого смаку. Найкращі запилювачі: Бере Боск, Десертна, Таврійська, Смарагдова, Марія, Мрія. Знімальна зрілість плодів настає у Криму – 20 вересня – 10  жовтня. У холодильнику  плоди добре зберігаються до березня. Стійкість до грибкових хвороб висока в умовах степового Криму. ','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i17742c99ecd66600/version/1671650129/image.jpg',6),(117,'Олів\'є де Серр','зелене','Дуже вимогливий до ґрунтово-кліматичних умов. Дерева Олів\'є де Серр потребують захищеного, теплого, добре освітленого місця розташування і хорошого живильного, зрошуваного, легкого грунту. Не терпить низьких місць із близьким стоянням ґрунтових вод та близьким заляганням галечникового шару, а також засолених ґрунтів. ','Зимостійкість середня. ','Садівництво','Дерево середньоросле. Плоди середньої величини, масою (до 150г.), бувають і більші. Форма плоско-куляста, бергамотоподібна, з горбистою поверхнею, особливо біля чашечки. Шкірочка злегка шорстка, щільна, сіро-зелена, вкрита бурими точками і плямами, що утворюють біля основи і у верхівки суцільні іржаві плями. При дозріванні шкірочка стає темнувато-жовтою, іноді зі слабким рум\'янцем на сонячному боці. М\'якоть кремова, дуже соковита, щільна, тане, солодка з невеликим мигдальним присмаком, ароматна, з легкою грануляцією навколо насіннєвого гнізда. За своїми смаковими якостями це один із найкращих пізньо-зимових сортів груші. Сорт частково самоплідний. Найкращі запилювачі: Вільямс, Улюблениця Клаппа, Деканька зимова. Плоди тримаються на дереві міцно. Знімальна зрілість настає у першій декаді жовтня, споживча у грудні. У лежці вони зберігаються до березня. З метою кращого зимового зберігання знімання плодів необхідно проводити якнайпізніше, з урахуванням погодних умов. Плоди транспортабельні. Сорт стійкий до парші.  ','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i18d4a7f77fef043e/version/1678113294/image.jpg',6),(118,'Вітчизняна','зелене','Не вимогливий до умов вирощування.','Зимостійкість середня. ','Садівництво','Дерево середньоросле. Плоди великі, масою (200-245г.), мах - (600г.), грушоподібні або коротко-грушоподібні, широко ребристі. Вершина плода широка, плоско куляста, основа коротка і тупа. Поверхня плода горбиста. Шкірочка тоненька, але міцна, суха. Основне забарвлення в період знімальної зрілості - зеленувато-жовте, покривне - незначний блідо-рожевий рум\'янець. Вся поверхня плоду вкрита добре помітними дрібними, зеленими або сірими підшкірними цятками та іржавими плямами. М\'якоть кремова, дуже соковита, масляниста, з легким ароматом троянди, відмінного, кисло-солодкого смаку. Цвіте у пізні терміни. Частково самоплідний сорт. Найкращі запилювачі: Десертна, Деканка зимова, Васса, Таврійська, Бере Боск, Олів\'є де Серр, Деканка дю Коміс, Якимівська, Смарагдова, Марія. Знімальна зрілість в умовах Криму настає – 20 вересня – 10 жовтня. Плоди міцно утримуються на дереві. У сховищах не втрачають смакових якостей до січня. Стійкий до грибкових хвороб та «термічного опіку» листя. Паршею не уражується.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/i29feeb46b35e430b/version/1678467556/image.jpg',6),(119,'Пам\'ять князю Трубецькому','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока.','Садівництво','Дерево середньоросле. Плоди великі і дуже великі, масою (300-800г.), широко-грушоподібної форми. Шкірочка зеленувато-жовта, з гарним рум\'янцем на більшій поверхні плоду. М\'якоть щільна, грубувата, напівмасляниста, з легким ароматом, солодка, високих смакових якостей. У звичайних умовах плоди придатні до вживання січень-лютий. Зберігаються в холодильнику – до квітня. При зберіганні не в’януть. Прекрасний ринковий сорт із тривалим терміном зберігання. Особливо покращується смак після зберігання та дозарювання при кімнатній температурі протягом 7-10 днів. Стійкість до грибкових хвороб висока.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/ibeb8040b8c4808dc/version/1671649858/image.jpg',6),(120,'Ракета','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока.','Садівництво','Дерево слабо- або середньоросле. Плоди великі, масою (210-410г.), довгасто-грушоподібної форми. Шкірочка жовта, покрита червоним рум\'янцем і суцільною крапчастою оржавленністю. М\'якоть кремова, середньої щільності, трохи хрустка, не масляниста, соковита, кисло-солодка, дуже гарного смаку. Дозрівають плоди - 10-15 жовтня. Зберігаються в звичайному підвалі до квітня. Стійкість до грибкових хвороб висока.','https://image.jimcdn.com/app/cms/image/transf/none/path/s2bf7bf36b3cc98c5/image/ib283e52747427dbc/version/1678370838/image.jpg',6),(121,'Чачакська Лепотіка','зелене','глинистий або суглинистий, родючий, повітропроникний грунт, достатньо вологий і без близького залягання грунтових вод.','Зимостійкість висока.','Садівництво','Дерево середньоросле. Плоди: Повноцінне плодоношення слива починає на 3-4 рік після висадки саджанців. Щороку в перших числах серпня Слива Чачакська Лепотіка радує своїх господарів соковитими плодами чудового десертного смаку великого розміру (40-50г) високого товарного зовнішнього вигляду, тривалим терміном зберігання (відмінний промисловий сорт). Плоди овальної форми, темно-гранатового кольору з властивим для слив сизим нальотом. М\'якоть плоду зеленувато-жовта, досить щільної, але соковитої консистенції. Довгаста кісточка з легкістю вилучається з м\'якоті Слива Чачакська Лепотіка - частково самоплідний сорт. цей сорт сливи служить відмінним запилювачем для інших сортів.','https://proxima.net.ua/image/cache/catalog/product_images/main_photo/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%BE%D0%BC%D0%B0%D1%88%D0%BD%D1%8F%D1%8F%20%D0%A7%D0%B0%D1%87%D0%B0%D0%BA%D1%81%D0%BA%D0%B0%D1%8F%20%D0%9B%D0%B5%D0%BF%D0%BE%D1%82%D0%B8%D0%BA%D0%B0%20%20%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%BE%D0%BC%D0%B0%D1%88%D0%BD%D1%8F%20%D0%A7%D0%B0%D1%87%D0%B0%D0%BA%D1%81%D1%8C%D0%BA%D0%B0%20%D0%9B%D0%B5%D0%BF%D0%BE%D1%82%D1%96%D0%BA%D0%B0%20%20Prunus%20domestica%20Chachak%20Lepotika-410x615.jpg',7),(122,'Слива колоноподібна Рубін (рання)','зелене','до ґрунту Prunus Rubin не вимоглива, любить легкий родючий вологий ґрунт. Не любить близького залягання ґрунтових вод.','Зимостійкість висока.','Садівництво','Опис сорту: невелике (до 2м) деревце раннього строку дозрівання колоноподібної форми, з великими плодами, на підщепі алича (починає плодоносити вже на другий рік після посадки). Українські садівники вже встигли оцінити цей компактний і дуже врожайний сорт сливового дерева. Самим виграшним при посадці даного сорту є розмір плодів, рясність плодоношення і компактність самого дерева що полегшує процес догляду та збору врожаю. дерево росте не швидко. Плоди: від червоного до рожево-фіолетового кольору, округлої форми, великі (масою 50-60 г) надзвичайно смачні. М\'якоть бурштинового кольору, кисло-солодка, кісточка легко відділяється. Дозріває в серпні. Світло: сорт сливи Рубін надає перевагу сонячним місцям, але може рости і в затіненні. На сонячній ділянці плоди будуть більші за розміром та в більшій кількості. плоди цього сорту дуже великі і смачні, а за рахунок своєї щільної шкірки здатні транспортуватися на тривалі відстані. сорт колоноподібної сливи Рубін – самоплідний та не вимагає запилювача.','https://proxima.net.ua/image/cache/catalog/product_images/vova%20foto/Prunus%20%D1%81olumnar%20Rubin%20/000001-777x777-product_popup.jpg',7),(123,'Слива біла Медова (рання)','зелене','суглинисті (средньоглинисті) або піщані ґрунти.','високу стійкість до сильних морозів і весняних заморозків, переносить посуху.','Садівництво','Запилювачі: Угорка рання, Ренклод Карбишева, Угорка Донецька рання. Опис сорту: ранньостиглий сорт сливи, який відрізняється незвичайним для цих плодів кольором і ніжним медовим ароматом. Слива Медова невибаглива до умов зростання, має високі показники врожайності, тому популярна в усіх регіонах України. Швидкість зростання / сила росту: спостерігається швидкий ріст в перші роки, який в період плодоношення сповільнюється. Плоди: за зовнішнім виглядом нагадують аличу, округлі, досить великі, вагою 30-50 грам. Шкірочка щільна, яскраво-жовтого кольору з легким восковим нальотом (див. фото). З сонячної сторони з\'являється невеликий оранжевий рум\'янець. М\'якоть жовта, іноді зелено-жовта, на смак солодка з приємною кислинкою і відмінним медовим післясмаком. Кісточка середніх розмірів, від м\'якоті відділяється важко. Дозрівають плоди в першій половині липня. Ставлення до світла / інсоляція: місце для посадки сливи має бути сонячним і захищеним від вітрів; в тіні листя блідніє, знижується якість плодів.','https://proxima.net.ua/image/cache/catalog/product_images/main_photo/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B1%D0%B5%D0%BB%D0%B0%D1%8F%20%D0%9C%D0%B5%D0%B4%D0%BE%D0%B2%D0%B0%D1%8F%20(%D1%80%D0%B0%D0%BD%D0%BD%D1%8F%D1%8F)%20%20%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B1%D1%96%D0%BB%D0%B0%20%D0%9C%D0%B5%D0%B4%D0%BE%D0%B2%D0%B0%20(%D1%80%D0%B0%D0%BD%D0%BD%D1%8F)%20%20Prunus%20domestica%20Medova-410x615.jpg',7),(124,'Слива домашня Кабардинка (рання)','зелене','до ґрунту слива Kabardinka не вимоглива, любить легку родючу вологу землю. Не любить близького залягання ґрунтових вод. Посухостійка, може переносити тривалу повітряну посуху спекотного літа.','на перезволожених ґрунтах, особливо на низовинах, молоді пагони можуть пошкоджуватися морозами.','Садівництво','Запилювачі: Ренклод, Угорка, Скороспілка червона. Опис сорту: середньоросле дерево на підщепі Пуміселект, швидкоплідне з округло-овальною кроною і великими пурпурно-фіолетовими плодами. Плоди: великі (близько 50 г.), округлої фори, пурпурового кольору з невеликим фіолетово-сизим нальотом. М\'якоть плодів щільна темно-жовтого кольору, соковита, дуже солодка з особливою незначною кислинкою і приємним ароматом. За своїми смаковими якостями плодів сорт Кабардинка займає перше місце серед всього асортименту ранніх сортів слив. Кісточка добре відділяється від м\'якоті. Плоди збирають в кінці червня. Завдяки тому, що рослина на підщепі пуміселект, перший урожай можна очікувати на другий рік після посадки. Молоді дерева плодоносять щорічно, а більш дорослі - в меншому обсязі або раз в два роки. Ставлення до світла / інсоляція: слива Кабардинка надає перевагу сонячним місцям, але може рости і в затіненні. Не страждає від сильних вітрів і посухи.','https://proxima.net.ua/image/cache/catalog/product_images/main_photo/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%BE%D0%BC%D0%B0%D1%88%D0%BD%D1%8F%D1%8F%20%D0%9A%D0%B0%D0%B1%D0%B0%D1%80%D0%B4%D0%B8%D0%BD%D0%BA%D0%B0%20(%D1%80%D0%B0%D0%BD%D0%BD%D1%8F%D1%8F)%20%20%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%BE%D0%BC%D0%B0%D1%88%D0%BD%D1%8F%20%D0%9A%D0%B0%D0%B1%D0%B0%D1%80%D0%B4%D0%B8%D0%BD%D0%BA%D0%B0%20(%D1%80%D0%B0%D0%BD%D0%BD%D1%8F)%20%20Prunus%20domestica%20Kabardinka-410x615.jpg',7),(125,'Слива домашня Кубанська (рання)','зелене','суглинисті (средньоглинисті) або піщані ґрунти.','Сорт морозостійкий','Садівництво','Запилювачі: Ренклод Альтана, Кабардинська рання. Опис сорту: ранньостиглий сорт з великими фіолетовими плодами, кисло-солодкими на смак. Швидкість зростання/сила росту: спостерігається швидке зростання в перші роки, яке в період плодоношення сповільнюється. Плоди: великі, вагою 60-80 грам, за формою нагадують овал (див. фото). Шкірочка насиченого фіолетового кольору, середньої товщини, з невеликим восковим нальотом, відділяється важко. М\'якоть жовта, соковита, на смак кисло-солодка. Кісточка невелика, від м’якоті відстає не повністю. Плоди дозрівають в середині липня. Ставлення до світла/інсоляція: місце для посадки сливи має бути сонячним і захищеним від вітрів; в тіні листя блідніють, знижується якість плодів. Має імунітет до полістигмозу.','https://proxima.net.ua/image/cache/catalog/product_images/2/imgonline-com-ua-Resize-tYHSctBs2tZe-777x777-product_popup.jpg',7),(126,'Слива домашня Ренклод ранній','зелене','суглинисті (средньоглинисті) або піщані ґрунти.','висока морозостійкість дерева і квіткових бруньок, стійкість до посухи','Садівництво','Синоніми: Слива Ренклод ранній. Опис сорту: самий ранній сорт з групи Ренклод, який вступає в плодоношення на 4-5 рік. Жовті плоди мають чудовий десертний смак і виражений сливовий аромат. Швидкість зростання / сила росту: спостерігається швидке зростання в перші роки, яке в період плодоношення сповільнюється. Плоди: у молодих дерев вага плодів становить близько 50 грам, з часом вона зменшується до 35-40 грам. Форма округла, злегка приплюснута. Поверхня зеленувато-жовта, при дозріванні - яскраво жовта, іноді з\'являється рум\'янець, щільна, прозора (див. фото). М\'якоть жовта з зеленим відтінком, соковита, на смак кисло-солодка з медовим присмаком. Виражений сливовий аромат. Кісточка відділяється складно. Час дозрівання: кінець липня-початок серпня. Ставлення до світла / інсоляція: місце для посадки сливи має бути сонячним і захищеним від вітрів; в тіні листя блідніє, знижується якість плодів.','https://proxima.net.ua/image/cache/catalog/product_images/main_photo/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%BE%D0%BC%D0%B0%D1%88%D0%BD%D1%8F%D1%8F%20%D0%A0%D0%B5%D0%BD%D0%BA%D0%BB%D0%BE%D0%B4%20%D1%80%D0%B0%D0%BD%D0%BD%D0%B8%D0%B9%20%20%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%BE%D0%BC%D0%B0%D1%88%D0%BD%D1%8F%20%D0%A0%D0%B5%D0%BD%D0%BA%D0%BB%D0%BE%D0%B4%20%D1%80%D0%B0%D0%BD%D0%BD%D1%96%D0%B9%20%20Prunus%20domestica%20Renklod%20ranniy-410x615.jpg',7),(127,'Слива колоновидна Біла Медова (рання)','зелене','суглинисті (средньоглинисті) або піщані ґрунти.','має високу стійкість до сильних морозів і весняних заморозків, переносить посуху.','Садівництво','Синоніми: Слива жовта Медова, жовта слива. Запилювачі: Угорка рання, Ренклод Карбишева, Угорка Донецька рання. Опис сорту: ранньостиглий сорт сливи, який відрізняється незвичайним для цих плодів кольором і ніжним медовим ароматом. Слива колоновидна Медова невибаглива до умов зростання, має високі показники врожайності, тому популярна в усіх регіонах України. Швидкість зростання / сила росту: спостерігається швидкий ріст в перші роки, який в період плодоношення сповільнюється. Плоди: за зовнішнім виглядом нагадують аличу, округлі, досить великі, вагою 30-50 грам. Шкірочка щільна, яскраво-жовтого кольору з легким восковим нальотом (див. фото). З сонячної сторони з\'являється невеликий оранжевий рум\'янець. М\'якоть жовта, іноді зелено-жовта, на смак солодка з приємною кислинкою і відмінним медовим післясмаком. Кісточка середніх розмірів, від м\'якоті відділяється важко. Дозрівають плоди в першій половині липня.','https://proxima.net.ua/image/cache/catalog/product_images/main_photo/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%BA%D0%BE%D0%BB%D0%BE%D0%BD%D0%BE%D0%B2%D0%B8%D0%B4%D0%BD%D0%B0%D1%8F%20%D0%91%D0%B5%D0%BB%D0%B0%D1%8F%20%D0%9C%D0%B5%D0%B4%D0%BE%D0%B2%D0%B0%D1%8F%20(%D1%80%D0%B0%D0%BD%D0%BD%D1%8F%D1%8F)%20%20%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%BA%D0%BE%D0%BB%D0%BE%D0%BD%D0%BE%D0%B2%D0%B8%D0%B4%D0%BD%D0%B0%20%D0%91%D1%96%D0%BB%D0%B0%20%D0%9C%D0%B5%D0%B4%D0%BE%D0%B2%D0%B0%20(%D1%80%D0%B0%D0%BD%D0%BD%D1%8F)%20%20Prunus%20domestica%20%D1%81olumnar%20Medova-410x615.jpg',7),(128,'Слива диплоїдна Флавор Квін (середня)','зелене','слива любить легкий, родючий, вологий ґрунт. Не любить близького залягання ґрунтових вод.','Сорт морозостійкий','Садівництво','Синоніми: плуот Флавор Квін, Флейвор Квін, Флевор Квін, зелена цукерка, Prunus salicina x armeniaca Flavor Queen. Запилювачі: для запилення потрібна інша японська слива або міжвидовий гібрид, який містить японську сливу. Опис сорту: Flavour Queen Pluot - це новий і виразний сорт, який характеризується інтенсивним, напіврозкидистим ростом і є продуктивним і регулярним носієм солодких цукрових плодів великих розмірів.  Сливи із сяючою зеленувато-жовтою шкіркою та красивою м’якоттю бурштинового кольору відзначаються гладкою оксамитовою текстурою та насиченим солодким смаком. Це один з найсолодших сортів серед плуотів. Сезон фруктів зазвичай припадає на пізнє літо. The Flavor Queen Pluot цінується за свій унікальний смак, який є сумішшю солодкості сливи та гостроти абрикоса. Потребує профілактичної обробки від шкідників та хвороб. Плоди: великі, вагою 80-100 грам, округлої форми. Шкірка зеленувато-жовта, тонка, без опушення. М’якоть янтарно-жовта, середньої щільності, дуже солодка (з високим вмістом цукрів), соковита, ароматна, з присмаком абрикоса. Кісточка маленька, відділяється важко. Знімна зрілість настає в середині серпня. Фрукти Flavour Queen, як правило, залишаються твердими на дереві протягом 12-15 днів після зрілості. Світло: надає перевагу сонячним місцям, але може рости і в тіні. На сонячній ділянці плоди будуть більші за розміром та в більшій кількості.','https://proxima.net.ua/image/cache/catalog/product_images/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%B8%D0%BF%D0%BB%D0%BE%D1%97%D0%B4%D0%BD%D0%B0%20%D0%A4%D0%BB%D0%B0%D0%B2%D0%BE%D1%80%20%D0%9A%D0%B2%D1%96%D0%BD%20(%D1%81%D0%B5%D1%80%D0%B5%D0%B4%D0%BD%D1%8F)/0-410x615.jpg',7),(129,'Слива домашня Блек Джем (середня)','зелене','до ґрунту слива не вимоглива, любить легкий родючий вологий ґрунт. Не любить близького залягання ґрунтових вод.','досить морозостійкий','Садівництво','Опис сорту: Слива Блек Джем - сорт середнього терміну дозрівання з відмінними смаковими якостями. Плоди темно-фіолетового кольору, що переходить практично в чорний. На смак солодкі, соковиті, ароматні. Сорт сливи Блек Джем досить морозостійкий, витривалий щодо хвороб, високоврожайний. Плоди: великі, вагою 45-55 грам, овальної форми. Шкірка темно-фіолетова, а при повному дозріванні - чорна, з блакитним восковим нальотом. М’якоть жовто-зелена, щільна, солодка на смак, соковита, ароматна. Кісточка добре відділяється. Знімна зрілість настає в середині серпня. Світло: надає перевагу сонячним місцям, але може рости і в тіні. На сонячній ділянці плоди будуть більші за розміром та в більшій кількості. Переваги:  висока врожайність, стійкість сорту до захворювань, товарність, транспортабельність, високі смакові якості, середньорослість, швидкоплідність. Цінується за високі десертні якості, вживаються в свіжому вигляді, а також для переробки. Прекрасний варіант для виготовлення чорносливу.','https://proxima.net.ua/image/cache/catalog/product_images/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%BE%D0%BC%D0%B0%D1%88%D0%BD%D1%8F%20%D0%91%D0%BB%D0%B5%D0%BA%20%D0%94%D0%B6%D0%B5%D0%BC%20(%D1%81%D0%B5%D1%80%D0%B5%D0%B4%D0%BD%D1%8F)/0-410x615.jpg',7),(130,'Слива домашня Ненька (середня)','зелене','слива Ненька не вимоглива до ґрунту, надає перевагу родючій, легкій, злегка вологій землі, погано реагує на близьке розташування ґрунтових вод.','морозостійкий','Садівництво','Плоди: плоди сорту Nenka великі (45-55 г), бочковидної форми типу угорок з невеликим швом. Забарвлення ягід фіолетово-бордове із сизим нальотом. Невеликих розмірів кісточка, легко відділяється від м\'якоті. М\'якоть жовто-зеленого кольору, пружна, приємного кисло-солодкого смаку. Дозрівання плодів настає на початку серпня, одночасно. Плоди мають відмінні товарні і споживчі характеристики. Ставлення до світла / інсоляція: слива любить сонячні місця або напівтінь. Сорт характеризується високою стійкістю до грибкових захворювань.','https://proxima.net.ua/image/cache/catalog/product_images/main_photo/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%BE%D0%BC%D0%B0%D1%88%D0%BD%D1%8F%D1%8F%20%D0%9D%D1%8D%D0%BD%D1%8C%D0%BA%D0%B0%20(%D1%81%D1%80%D0%B5%D0%B4%D0%BD%D1%8F%D1%8F)%20%20%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%B4%D0%BE%D0%BC%D0%B0%D1%88%D0%BD%D1%8F%20%D0%9D%D0%B5%D0%BD%D1%8C%D0%BA%D0%B0%20(%D1%81%D0%B5%D1%80%D0%B5%D0%B4%D0%BD%D1%8F)%20%20Prunus%20domestica%20Nenka-410x615.jpg',7);
INSERT INTO `sorts` VALUES (131,'Слива Бербанк Гігант (диплоїдна)','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока','Садівництво','Плоди і справді гігантські, їх вага варіюється від 150 до 220г, окремі можуть досягати 250 г при належному догляді. Шкірочка фіолетово-синя, темна з невеличкими світлими вкрапленнями та невеличким матовим нальотом. М\'якуш темно-бордового кольору, соковита, ароматна, щільна, чудового кисло-солодкого смаку з великим вмістом цукру. Кісточка маленька та частково відділяється. Дерево середньоросле, та стійке до морозів та хвороб. Проте може уражатись плодовою гниллю, тому варто своєчасно обробляти, щоб вберегти плоди. ','https://litynsad.com.ua/sites/default/files/styles/1920x1080m/public/product_images/sliva-berbank-gigant_1.jpg?itok=wf4N5SCM',7),(132,'Слива Блек Амбер (диплоїдна)','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока','Садівництво','Дерево середньоросле. Знімна зрілість плодів припадає на початок-середину серпня. Плоди великі, 100-150г, темно синього кольору з сизим восковим нальотом, приплюснуті зверху і знизу, округлої форми. М\'якуш світло-жовта, щільна, м\'ясиста, соковита та дуже ароматна. Смак дуже приємний та збалансований, кисло-солодкий. Кісточка відділяється разом з частинками врослої м\'якоті. Стійкість до морозів, засухи та хвороб дуже висока. Запилювати можна будь-якими іншими сортами диплоїдних слив. Найкращі запильники: слива Анжеліно, слива Байрон Голд, слива ТоЧеСан, слива Прайм-тайм, слива Санта Роза.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/sliva-black-amber_2.jpg?itok=hYU-EHji',7),(133,'Слива Блек Джем','зелене','Не вимогливий до умов вирощування.','Зимостійкість вище середнього','Садівництво','Плоди середні, масою 45-50г, овальної форми. Шкірка темно-фіолетова, вкрита світло-синім нальотом, досягаючи повної зрілості, шкірка стає майже чорного кольору. М\'якуш жовто-зеленого кольору, щільна, соковита, солодка та дуже ароматна. Кісточка добре відділяється. Зимостійкість та стійкість до хвороб високі, рекомендовані профілактичні обробки від хвороб. Сорт самоплідний, але якщо висадити його з заплідниками то можна отримати рясніші врожаї.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/sliva-black-jam_2.jpg?itok=bhWcyW6A',7),(134,'Слива Валор','зелене','Не вимогливий до умов вирощування.','Зимостійкість висока','Садівництво','Дерево середньоросле. Плоди крупні, масою 60-90г, яйцеподібної форми. Шкірка тонка, щільна, з сильним восковим нальотом, рожево-фіолетовго кольору. М\'якуш зеленувато-кремова, на повітрі не темніє, волокниста, ніжна, соковита, ароматна, солодкого відмінного смаку. Кісточка легко відділяється. Слива Валор показує високу стійкість до морозів та хвороб, проте рекомендується проводити профілактичні обробки. Рекомендовано висаджувати на ділянках, де багато сонця.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/sliva-valor_2.jpg?itok=PskNglqq',7),(135,'Слива Голлівуд','червоне','Не вимогливий до умов вирощування.','Зимостійкість вище середнього','Садівництво','Дерево середньоросле. Знімна зрілість плодів настає в середині серпня. Плоди середнього розміру 50-80гр овально-округлої форми. Шкірка фіолетово-червона з густим восковим нальотом. М\'якуш жовта з рожевим відтінком, ніжна, солодка з кислинкою, тане у роті. Кісточка легко відділяється. Стійкість до хвороб та холодів достатньо висока, щоб вирощувати даний сорт на всій території України. Слива Голлівуд має дуже гарне листя червоного кольору, що забезепечує чудовий декоративний вигляд. Її часто використовують як декоративне дерево з якого також можна збирати плоди, чудовий вибір для дизайнів ландшафтів.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/sliva-gollivud_4.jpg?itok=CEcLSKNW',7),(136,'Слива Гек','зелене','Не вимогливий до умов вирощування.','Зимостійкість вище середнього','Садівництво','Дерево  сильноросле. Сорт є врожайним але самобезплідним, тому потрібно висаджувати з іншими запильниками. Плоди не великі, в середньому 35-50г. Шкірка еластична, жовта з невеликим рум\'янцем на сонці до 25% поверхні, з восковим нальотом середньої густоти. М’якуш жовтий, тонкозернистий, середньої щільності, приємного кисло-солодкого смаку. Стійкість до хвороб та холодів вище середнього, рекомендується проводити профілактичні обробки від хвороб та шкідників.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/gek_2.jpg?itok=wRAWTHvO',7),(137,'Слива Суперіор (диплоїдна)','зелене','Полюбляє плодородні, рихлі ґрунти та сонячні місця.','Зимостійкість вище середнього','Садівництво','Плоди вирізняються великим розміром, масою 50-70 г, оранжево-пурпурним кольором з восковим нальотом і чудовими смаковими якостями. М’якоть щільна, світло-червона, з приємним ароматом. Кісточка щільно сидить у м\'якоті. не піддається хворобам і шкідникам, таким як шарка і плодожерка. Зимостійкість вище середнього рівня, що дозволяє вирощувати цей сорт в різних кліматичних умовах. Врожайність дуже висока, дозрівання плодів на початку серпня. Завдяки своїй щільності, плоди добре зберігаються при низьких температурах.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/superior_2.jpg?itok=5gY0bVkW',7),(138,'Слива Формоза','зелене','У розпушеному землі саджанець швидко піде в зростання і почне плодоносити набагато раніше.','Зимостійкість вище середнього','Садівництво, декоративне','Дерево цього сорту середньоросле. Плоди \"Формози\" великі, вагою від 80 грамів і більше, ароматні, солодкі та дуже смачні, дозрівають на початку серпня. Кісточка не відокремлюється від м\'якоті плоду. Несиметрична, овальна форма з характерним загостренням у верхній частині. Шкірка плоду жовто-червона гладка, слизька, з численними світлими цятками та свердлять восковим нальотом. М\'якоть плоду жовта, соковита. Досить стійкий до плямистостей листя кісточкових. Посадка: Перед початком посадки, слід обробити грунт на місці закладки саду, позбутися від бур\'янів і глибоко розпушити грунт, щоб до коріння вільно поступало повітря, а щільна грунт не гальмувала їх зростання і проникнення вглиб землі. Даний прийом убезпечить дерево від швидкого старіння, і сад зможе радувати рясним врожаєм багато років. У розпушеному землі саджанець швидко піде в зростання і почне плодоносити набагато раніше.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/sliva-formoza4.jpg?itok=J76G3A-t',7),(139,'Слива Угорка рання','зелене','Не вимогливий до умов вирощування.','Зимостійкість середня','Садівництво','Дерева середньорослі. Плоди середнього розміру, правильної, трохи подовженої форми, насиченого синього кольору з красивим фіолетово-червоним відтінком, вагою до 100 г. Довго не обсипаються після дозрівання. Сорт має високі смакові якості, придатний для приготування чорносливу. М\'якоть жовто-зелена або золотисто-бурштинова, щільна і пружна, приємного десертного смаку. Кісточка невелика, легко відділяється. Сорт \"Угорка\" популярний у всіх областях України, добре переносить вологу і не дуже суворі морози, після яких самостійно відновлюється. Самоплідний сорт, який не вимагає запилювачів, але з іншими сортами плодоношення буде кращим.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/vengerka-rannyaya_1.jpg?itok=HWGdETUQ',7),(140,'Слива Ренклод зелений','зелене','родючим, добре дренованим ґрунтом.','Зимостійкість вище середнього','Садівництво','Дерево швидко росте. Цей сорт самобезплідний, тому йому потрібні запилювачі. Плоди дозрівають у третій декаді серпня. Сливи цього сорту мають тонку зеленувато-жовту шкірку, покриту густим нальотом. Бік плоду з сонячної сторони жовтий із рудуватими плямами. Плоди великі, вагою 35-45 г, мають округлу форму і трохи плескаті з полюсів. М\'якоть зеленувато-жовта, ніжно-волокниста і медово-солодка. Шкірка легко з\'їдається, тонка, зелена з густим сизим нальотом, а невелика кісточка трохи приросла до м\'якоті. Саджанці найкраще приживаються на добре освітлених ділянках з родючим, добре дренованим ґрунтом. Рясний полив необхідно проводити кілька разів на сезон, але не в період дозрівання плодів. Варто слідкувати за можливими шкідниками та захворюваннями, хоча сорт має середню стійкість до захворювань, регулярний огляд дерев допоможе запобігти поширенню проблем. Потрібно спостерігати за сливами у вологу погоду, оскільки вони можуть розтріскуватися і гнити. При високому врожаї встановлювати підпори, щоб гілки не ламалися під вагою плодів.','https://litynsad.com.ua/sites/default/files/styles/570x415/public/product_images/sliva-renklod-zeleny_2.jpg?itok=ER38qpQH',7),(141,'Слива Амерс (Amers)','зелене','Не вимогливий до умов вирощування.','Морозостійкість висока. Посухостійкість висока','Садівництво','Дерева середньорослі. Сорт частково самоплідний, але краще плодоношення настає при запиленні іншими сортами слив. Кращими запилювачами є сорти \"Стенлі\" (Stanley), \"Блюфрі\" (Blufree), \"Президент\" (President), \"Угорка\", \"Чачакська Рання\" (Čačanska rana). Плоди сливи великі, овальної форми, трохи приплюснуті. Колір відрізняється красивим гранатовим відтінком з характерним ніжно-блакитним восковим нальотом. Інтенсивність забарвлення залежить від освітлення, сорт прихильно ставиться до сонячного світла, тому потребує проріджування крони в літній час. М\'якоть насичено-жовтого або помаранчево-жовтого кольору, дуже щільна, яка нагадує по консистенції абрикос, що є унікальною властивістю для сливи. Кісточка добре відділяється. Термін дозрівання – середина вересня. Дерева починають плодоносити на 2-3 рік.','https://biosad.ua/storage/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%90%D0%BC%D0%B5%D1%80%D1%81_%D1%81%D0%B0%D0%B6%D0%B5%D0%BD%D1%86%D1%8B_%D0%91%D0%B8%D0%BE%D1%81%D0%B0%D0%B4_1%20(%D0%9A%D0%BE%D0%BF%D0%B8%D1%80%D0%BE%D0%B2%D0%B0%D1%82%D1%8C).jpg',8),(142,'Слива Анна Шпет (Anna Späth) ','зелене','Не вимогливий до умов вирощування.','Морозостійкість середня. Посухостійкість висока','Садівництво','Дерева сильнорослі. Сорт частково самоплідний, але краще плодоношення настає при запиленні іншими сортами слив. Хорошими запилювачами стануть сорти \"Угорка\" і \"Блюфрі\". Плоди сливи великі, овальної форми. Колір фіолетовий з красивим гранатовим відтінком. Довго не обсипаються, навіть після повного дозрівання. М\'якоть жовто-зеленого кольору, щільна, приємного десертного смаку. Кісточка невелика, добре відділяється. Термін дозрівання: кінець вересня – початок жовтня.','https://biosad.ua/storage/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%90%D0%BD%D0%BD%D0%B0%20%D0%A8%D0%BF%D0%B5%D1%82__%D1%81%D0%B0%D0%B6%D0%B5%D0%BD%D1%86%D1%8B_%D0%91%D0%B8%D0%BE%D1%81%D0%B0%D0%B4%20(%D0%9A%D0%BE%D0%BF%D0%B8%D1%80%D0%BE%D0%B2%D0%B0%D1%82%D1%8C).jpg',8),(143,'Слива Емпресс (Empress)','зелене','Не вимогливий до умов вирощування.','Посухостійкість хороша. Морозостійкість хороша','Садівництво','Дерева середньорослі. Сорт частково самоплідний, для поліпшення показників урожайності та якості можна посадити поруч інші сорти слив: \"Стенлі\", \"Блюфрі\", \"Президент\". Плоди сливи великих розмірів, овально-округлої форми. Колір бордово-фіолетовий, повністю вкритий слабким восковим нальотом. М\'якоть зеленувато-жовта, досить щільна, соковита і солодка, з легкою кислинкою. Кісточка середня, легко відділяється. Термін дозрівання – початок жовтня. Невибагливість у догляді, міцний імунітет.','https://biosad.ua/storage/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%AD%D0%BC%D0%BF%D1%80%D0%B5%D1%81%D1%81_2%20%D0%91%D0%B8%D0%BE%D1%81%D0%B0%D0%B4%20%D1%81%D0%B0%D0%B6%D0%B5%D0%BD%D1%86%D1%8B%20(%D0%9A%D0%BE%D0%BF%D0%B8%D1%80%D0%BE%D0%B2%D0%B0%D1%82%D1%8C).jpg',8),(144,'Слива Хаганта (Haganta) ','зелене','Не вимогливий до умов вирощування.','Морозостійкість висока. Посухостійкість висока','Садівництво','Дерева середньорослі. Сорт частково самоплідний, для гарного плодоношення і високої врожайності йому потрібні запилювачі. Приміром, підвищити показники врожайності даного сорту допоможуть \"Чачакська Лепотіка\" і \"Ханіта\". Плоди сливи \"Хаганта\" великі, красиві, овально-округлої форми. Колір глибокий, темно-синій, з щільним зеленим нальотом. М\'якоть красивого помаранчевого кольору, щільна, солодка та соковита. Кісточка невелика, легко відділяється. Термін дозрівання – середина вересня. Дерева починають плодоносити на 4-5 рік. Стійкий до хвороб.','https://biosad.ua/storage/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%A5%D0%B0%D0%B3%D0%B0%D0%BD%D1%82%D0%B0_%D0%91%D0%B8%D0%BE%D1%81%D0%B0%D0%B4_%D1%81%D0%B0%D0%B6%D0%B5%D0%BD%D1%86%D1%8B_1%20(%D0%9A%D0%BE%D0%BF%D0%B8%D1%80%D0%BE%D0%B2%D0%B0%D1%82%D1%8C).jpg',8),(145,'Слива Блюфрі (Bluefre)','зелене','Не вимогливий до умов вирощування.','Морозостійкість висока. Посухостійкість середня','Садівництво','Дерева середньорослі. Сорт самоплідний, не вимагає запилювачів, але для кращого плодоношення підійдуть такі сорти як \"Стенлі\", \"Президент\", \"Анна Шпет\". Плоди сливи \"Блюфрі\" досить великі, правильної овальної форми. Відрізняються прекрасним темно-фіолетовим відтінком з характерним восковим нальотом. М\'якоть жовтого кольору, щільна, насиченого десертного смаку. Кісточка – середнього розміру, відділяється погано. Термін дозрівання: середина вересня – початок жовтня. Дерева починають плодоносити на 3-4 рік. Має хороший імунітет.','https://biosad.ua/storage/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%91%D0%BB%D1%8E%20%D0%A4%D1%80%D0%B8_%D1%81%D0%B0%D0%B6%D0%B5%D0%BD%D1%86%D1%8B_%D0%91%D0%B8%D0%BE%D1%81%D0%B0%D0%B4_2%20(%D0%9A%D0%BE%D0%BF%D0%B8%D1%80%D0%BE%D0%B2%D0%B0%D1%82%D1%8C).jpg',8),(146,'Слива Президент (President)','зелене','Не вимогливий до умов вирощування.','Морозостійкість висока. Посухостійкість висока','Садівництво','Дерева сильнорослі. Сорт повністю самоплідний, не потребує запилювачів, але за наявності поруч інших сортів слив плодоношення буде набагато вище. Плоди \"Президента\" великі, округлої правильної форми. Основний колір плоду – зелений, по всій поверхні вкритий красивим бордово-фіолетовим нальотом з синім відтінком. М’якоть зелено-жовтого або жовтого кольору, ніжна, приємного кисло-солодкого смаку. Кісточка середнього розміру, легко відділяється. Термін дозрівання: кінець вересня – початок жовтня. Дерева починають плодоносити на 4-5 рік. тійкість до хвороб середня.','https://biosad.ua/storage/cache/16571904231390-573x351.webp',8),(147,'Слива Штутгард (Stuttgart)','зелене','Не вимогливий до умов вирощування.','Морозостійкість висока. Посухостійкість висока','Садівництво','Дерева сильнорослі. Сорт самоплідний, не вимагає запилювачів. Плоди сливи \"Штутгард\" дуже великі, овальної форми. Колір темно-гранатовий, майже чорний, з блакитним нальотом. М\'якоть бурштинового кольору, щільна і ароматна, приємним кисло-солодким смаком. Кісточка велика, добре відділяється. Термін дозрівання: середина вересня – початок жовтня. Дерева починають плодоносити на 3-4 рік. Має хороший імунітет проти хворіб.','https://biosad.ua/storage/cache/16572034621862-573x351.webp',8),(148,'Слива Віжен (Vision) ','зелене','Не вимогливий до умов вирощування.','Морозостійкість висока. Посухостійкість висока','Садівництво','Дерева середньорослі. Сорт не самоплідний, тому вимагає запилювачів. Кращими запилювачами є сорти \"Президент\" (President) і \"Стенлі\" (Stanley). Плоди сливи \"Віжен\" великі, подовженої форми. Колір насичений, темно-червоний, з легким блакитним нальотом. М’якоть красивого медового кольору, щільна, солодка і дуже соковита з легкою кислинкою. Кісточка середнього розміру, легко відділяється. Термін дозрівання: середина – кінець вересня. Дерева починають плодоносити на 4-5 рік. Стійкий до хворіб.','https://biosad.ua/storage/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%92%D0%B8%D0%B6%D0%B5%D0%BD_%D1%81%D0%B0%D0%B6%D0%B5%D0%BD%D1%86%D1%8B_%D0%91%D0%B8%D0%BE%D1%81%D0%B0%D0%B4_2%20(%D0%9A%D0%BE%D0%BF%D0%B8%D1%80%D0%BE%D0%B2%D0%B0%D1%82%D1%8C).jpeg',8),(149,'Слива Топ Хіт (Top Hit)','зелене','Не вимогливий до умов вирощування.','Морозостійкість висока. Посухостійкість середня','Садівництво','Дерева середньорослі. Сорт самоплідний, не вимагає запилювачів, але для кращого плодоношення підійдуть такі сорти як \"Чачакска Рання\" та \"Президент\". Плоди сливи \"Топ Хіт\" дуже великі, яйцеподібної пропорційної форми. Колір темно-фіолетовий, з блакитним нальотом. М\'якоть бурштинового кольору, щільна, приємного солодкого смаку з легкою кислинкою. Кісточка середнього розміру, добре відділяється. Термін дозрівання: кінець вересня – середина жовтня. Дерева починають плодоносити на 4-5 рік. Має хороший імунітет.','https://biosad.ua/storage/%D0%A1%D0%BB%D0%B8%D0%B2%D0%B0%20%D0%A2%D0%BE%D0%BF%20%D0%A5%D0%B8%D1%82_%D1%81%D0%B0%D0%B6%D0%B5%D0%BD%D1%86%D1%8B_%D0%91%D0%B8%D0%BE%D1%81%D0%B0%D0%B4_2%20(%D0%9A%D0%BE%D0%BF%D0%B8%D1%80%D0%BE%D0%B2%D0%B0%D1%82%D1%8C).png',8),(150,'Слива Волошка','зелене','Не вимогливий до умов вирощування.','Морозостійкість середня. Посухостійкість висока','Садівництво','Дерева сильнорослі. Сорт не самоплідний, тому вимагає запилювачів. Кращими запилювачами є сорти: \"Віжен\" (Vision), \"Топ Хіт\" (Top Hit), \"Анна Шпет\" (Anna Späth). Плоди сливи \"Волошка\" великі, овально-плескатої форми. Колір глибокий, темно-синій, іноді з зеленим або іржавим відтінком, плід сильно вкритий характерним сизим нальотом. М\'якоть красивого жовтого кольору, з ніжним зеленим відтінком, щільна, солодка і соковита, з легкою, приємною кислинкою. Кісточка невелика, легко відділяється. Термін дозрівання: середина вересня. Дерева починають плодоносити на 4 - 5 рік. Має хороший імунітет. Стійкість до парші середня. ','https://biosad.ua/storage/cache/16571025325034-573x351.webp',8);
INSERT INTO `sorts` VALUES (151,'Слива \"Яєчна жовта\"','зелене','Нейтральний','Морозостійкість:	- 25 С°','Садівництво','Плоди її досить великі, середньою вагою 40-50 грамів. Сливи мають правильну округлу форму і щільну гладку шкірку з тонким білим восковим нальотом. Забарвлення поверхні сонячне, яскраво-жовте. Зрідка на освітленому боці з\'являється світлий помаранчевий рум\'янець. М\'якуш теж жовтий, пружний, з великою кількістю соку. Смак солодкий, з легкою кислинкою та приємним медовим ароматом. Кісточка маленька і важковиділяється. Перші плоди: 1-2 рік. Місце посадки: Сонце/Напівтінь. Запилення: Бажано запилювач. Місяць дозрівання: Друга декада вересня.','https://kievsad.com.ua/sites/default/files/styles/webp/public/product/type-tree/2024-01/%D0%AF%D1%94%D1%87%D0%BD%D0%B0%20%D0%96%D0%BE%D0%B2%D1%82%D0%B0.jpg.webp?itok=MnVcqH0q',8),(152,'Слива \"Фріар\"','зелене','	Нейтральний','Морозостійкість середня.','Садівництво','Дерево середньоросле. Збирання врожаю в кліматичних умовах півдня України з другої декади вересня. Сливи Фріар відрізняється великими якісними плодами середньою масою 55 - 100 г, округлої форми, при повному дозріванні бордового забарвлення з малиновим відтінком. Шкірка щільна, що з\'їдається. М\'якуш рожево-жовтий, волокнистий, щільний, солодкий, ароматний, високих смакових якостей. Дегустаційна оцінка, 5 балів, кісточка добре відокремлюється. Стійка до захворювань. Найкращі запилювачі: Блек Амбер, Сатсума, Санта Роза, Оцарк Прем\'єр.','https://kievsad.com.ua/sites/default/files/styles/webp/public/product/type-tree/2024-01/%D0%A4%D1%80%D1%96%D0%B0%D1%80.jpg.webp?itok=O7nmwjfb',8),(153,'Слива \"Ельдорадо\"','зелене','	Нейтральний','Зимостійкий, підходить для вирощування у більшості районів України.','Садівництво','Дерево середньоросле. Плоди великої величини, їх маса 60-80 г, округла слива. Забарвлення шкірки темно-бордове, на поверхні є пруїновий наліт. М\'якуш соковитий, ущільнений, колір яскраво-жовтий. Смак приємний, солодкуватий із кислинкою. Кісточка крихітна, відокремлена від внутрішньої частини. Урожай збирають на початку осіннього періоду – приблизно з 1 по 10 вересня. Перші плоди: 2 рік. Місце посадки: Сонце/Напівтінь. Запилення: Бажано запилювач. Високостійкий до сливових хвороб.','https://kievsad.com.ua/sites/default/files/styles/webp/public/product/type-tree/2024-01/%D0%95%D0%BB%D1%8C%D0%B4%D0%BE%D1%80%D0%B0%D0%B4%D0%BE.png.webp?itok=7R187Lfb',8),(154,'Слива \"Топ Гігант\"','зелене','	Нейтральний','Стійке до заморозків. ','Садівництво','плоди темно-сині, з сизим нальотом, широкоовальні, масою від 60 до 100 г; м\'якоть зеленувато-жовта, м\'ясиста, солодка з кислинкою, кісточка вільна; період дозрівання — кінець серпня; імунітет до основних грибкових захворювань. Топ Гігант Плюс рекомендується на всіх форумах садівників як самоплідний, тому не потребує обпилювачів. Він дає перший урожай через 3-4 роки після посадки, з дорослого дерева збирають до 60 кг плодів. Користь слив — у багатому вітамінному «коктейлі» (містять РР, С, Е, групи В, мідь, калій, йод та ін.) і низькій калорійності (46 кал на 100 г продукту). Вживання плодів в їжу очищає організм від токсинів, зміцнює судини та серце. Місяць дозрівання: Кінець серпня. Місце посадки: Сонце/Напівтінь. ','https://kievsad.com.ua/sites/default/files/styles/webp/public/product/type-tree/2024-09/sliva-top-gigant_0.jpg.webp?itok=s1K1bMw2',8),(155,'Слива \"Пісарді\"','темно-бордове','	Нейтральний','Морозостійкість: - 25 С°','Садівництво, декоративне','Сорт декоративної сливи, вирізняється листям темно-червоного або бордового забарвлення протягом усього сезону. Квіти ніжно-рожеві, але з часом стають білими. Плоди темно-вишневі масою 20-30 грам, приємного кисло-солодкого смаку з ноткою терпкості. Дозрівають в серпні, на дереві тримаються до жовтня.','https://kievsad.com.ua/sites/default/files/styles/webp/public/product/type-tree/2024-01/%D0%9F%D1%96%D1%81%D0%B0%D1%80%D0%B4%D1%96.jpg.webp?itok=78JgbVCT',8);
